static size_t xstrsncpy(char *restrict dst, const char *restrict src, size_t n)
{
	char *end = memccpy(dst, src, '\0', n);
	if (!end) {
		dst[n - 1] = '\0';
		end = dst + n;
	}
	return end - dst;
}

static char *xbasename(char *path)
{
	char *base = strrchr(path, '/');
	return base ? base + 1 : path;
}

static char *xextension(const char *fname, size_t len)
{
	while (--len > 0)
		if (fname[len] == '.')
			return (char *)(fname + len);
	return NULL;
}

static char *xitoa(uint_t val)
{
	static char dst[32] = {'\0'};
	static const char digits[201] =
		"0001020304050607080910111213141516171819"
		"2021222324252627282930313233343536373839"
		"4041424344454647484950515253545556575859"
		"6061626364656667686970717273747576777879"
		"8081828384858687888990919293949596979899";
	uint_t i = 30;
	while (val >= 100) {
		uint_t quo = val / 100;
		uint_t rem = val - quo * 100;
		val = quo;
		memcpy(dst + i - 1, digits + rem * 2, 2);
		i -= 2;
	}
	if (val >= 10) {
		memcpy(dst + i - 1, digits + val * 2, 2);
		--i;
	} else
		dst[i] = '0' + val;
	return dst + i;
}

static void *xrealloc(void *pcur, size_t len)
{
