static char *common_prefix(const char *path, char *prefix)
{
	const char *x = path, *y = prefix;
	char *sep;

	if (!path || !*path || !prefix)
		return NULL;

	if (!*prefix) {
		xstrsncpy(prefix, path, PATH_MAX_LEN);
		return prefix;
	}

	while (*x && *y && (*x == *y))
		++x, ++y;

	/* Strings are same OR path is substring of prefix */
	if (!*x && (!*y || *y == '/'))
		return prefix;

	/* Path is prefix of prefix */
	if (!*y && *x == '/')
		return prefix;

	/* Shorten prefix */
	sep = strrchr(prefix, '/');
	if (sep != prefix) {
		*sep = '\0';
		return prefix;
	}
	prefix[1] = '\0';
	return prefix;
}

static bool is_prefix(const char *restrict str, const char *restrict prefix, size_t len)
{
	return !strncmp(str, prefix, len);
}

static bool is_suffix(const char *restrict str, const char *restrict suffix)
{
	size_t lenstr = strlen(str), lensuffix = strlen(suffix);
	if (lensuffix > lenstr)
		return false;
	return !strcmp(str + lenstr - lensuffix, suffix);
}

static char *getreadline(const char *prompt)
{
	char *input;

	exitcurses();
	input = readline(prompt);
	refresh();
	if (input && input[0]) {
		add_history(input);
		return input;
	}
	free(input);
	return NULL;
}

/* make a path, "path" must be absolute dir; returns len */
static size_t mkpath(const char *dir, const char *name, char *out)
{
	size_t len = 0;

	if (name[0] == '/')
		return xstrsncpy(out, name, PATH_MAX_LEN);

	if (dir[0] == '/' && !dir[1]) {
		out[0] = '/';
		len = 1;
	} else {
		len = xstrsncpy(out, dir, PATH_MAX_LEN);
		out[len - 1] = '/';
	}
	return len + xstrsncpy(out + len, name, PATH_MAX_LEN - len);
}

static char *abspath(const char *filepath, char *cwd, char *buf)
{
	const char *path = filepath;
	char *resolved;
	size_t len;

	if (!path)
		return NULL;

	if (path[0] == '~') {
		if (!homedir)
			return NULL;
		len = xstrsncpy(g_buf, homedir, CMD_LEN_MAX);
		xstrsncpy(g_buf + len - 1, path + 1, CMD_LEN_MAX - len);
		path = g_buf;
	}

	if (path[0] != '/' && cwd) {
		len = strlen(cwd);
		if (len + strlen(path) + 2 > PATH_MAX_LEN)
			return NULL;
		len = mkpath(cwd, path, buf ? buf : g_buf);
		path = buf ? buf : g_buf;
	}

	resolved = buf ? buf : malloc(PATH_MAX_LEN);
	if (!resolved)
		return NULL;

	{
		/* normalize: remove . and .. and duplicate slashes */
		char tmp[PATH_MAX_LEN];
		size_t n = xstrsncpy(tmp, path, PATH_MAX_LEN);
		char *out = resolved, *p = tmp, *seg;
		(void)n;
		out[0] = '/';
		out[1] = '\0';
		if (*p == '/')
			++p;
		while (*p) {
			seg = p;
			while (*p && *p != '/')
				++p;
			if (*p)
				*p++ = '\0';
			if (!*seg || !strcmp(seg, "."))
				continue;
			if (!strcmp(seg, "..")) {
				char *s = strrchr(out, '/');
				if (s && s != out)
					*s = '\0';
				else
					out[1] = '\0';
				continue;
			}
			{
				size_t ol = strlen(out);
				if (ol > 1) {
					out[ol++] = '/';
					out[ol] = '\0';
				}
				xstrsncpy(out + ol, seg, PATH_MAX_LEN - ol);
			}
		}
	}
	return resolved;
}

