static bool set_colors(void)
{
	char *colors = getenv("NNN_COLORS");
	char *fcol = getenv("NNN_FCOLORS");
	uint_t i;
	bool ctxcolor_set[CTX_MAX] = {0};

	for (i = 0; i < CTX_MAX; ++i)
		g_ctx[i].color = 4;

	if (colors && *colors) {
		if (*colors == '#') {
			char *c = colors + 1;
			size_t len = strlen(c);
			if (len & 1) {
				fprintf(stderr, "NNN_COLORS\n");
				return false;
			}
			for (i = 0; i < CTX_MAX && *c; ++i, c += 2) {
				char hex[3] = {c[0], c[1], '\0'};
				char *end;
				long v = strtol(hex, &end, 16);
				if (*end) {
					fprintf(stderr, "NNN_COLORS\n");
					return false;
				}
				g_ctx[i].color = (uint_t)v;
				ctxcolor_set[i] = true;
			}
		} else {
			for (i = 0; i < CTX_MAX && colors[i]; ++i) {
				if (colors[i] >= '0' && colors[i] <= '7')
					g_ctx[i].color = colors[i] - '0';
				else
					g_ctx[i].color = 4;
				ctxcolor_set[i] = true;
			}
		}
	}

