		}
		fcolors[C_BLK + i] = (uint_t)v;
	}

	if (!has_colors())
		return true;

	start_color();
	use_default_colors();

	for (i = 0; i < CTX_MAX; ++i)
		init_pair(C_CTX_BASE + i, g_ctx[i].color, -1);

	if (g_state.oldcolor) {
