static bool set_colors(void)
{
	char *colors = getenv("NNN_COLORS");
	char *fcol = getenv("NNN_FCOLORS");
	uint_t i;
	bool ctxcolor_set[CTX_MAX] = {0};

	for (i = 0; i < CTX_MAX; ++i)
		g_ctx[i].color = 4;

	if (colors && *colors) {
		if (*colors == '#') {
			char *c = colors + 1;
			size_t len = strlen(c);
			if (len & 1) {
				fprintf(stderr, "NNN_COLORS\n");
				return false;
			}
			for (i = 0; i < CTX_MAX && *c; ++i, c += 2) {
				char hex[3] = {c[0], c[1], '\0'};
				char *end;
				long v = strtol(hex, &end, 16);
				if (*end) {
					fprintf(stderr, "NNN_COLORS\n");
					return false;
				}
				g_ctx[i].color = (uint_t)v;
				ctxcolor_set[i] = true;
			}
		} else {
			for (i = 0; i < CTX_MAX && colors[i]; ++i) {
				if (colors[i] >= '0' && colors[i] <= '7')
					g_ctx[i].color = colors[i] - '0';
				else
					g_ctx[i].color = 4;
				ctxcolor_set[i] = true;
			}
		}
	}

	if (fcol && strlen(fcol) == 24)
		memcpy(gcolors, fcol, 24);

	for (i = 0; i <= C_UND - C_BLK; ++i) {
		char hex[3] = {gcolors[i * 2], gcolors[i * 2 + 1], '\0'};
		char *end;
		long v = strtol(hex, &end, 16);
		if (*end) {
			fprintf(stderr, "NNN_FCOLORS\n");
			return false;
		}
		fcolors[C_BLK + i] = (uint_t)v;
	}

	if (!has_colors())
		return true;

	start_color();
	use_default_colors();

	for (i = 0; i < CTX_MAX; ++i)
		init_pair(C_CTX_BASE + i, g_ctx[i].color, -1);

	if (g_state.oldcolor) {
		/* 8-color scheme: file type colors use a reduced palette */
		init_pair(C_BLK, COLOR_YELLOW, -1); /* unused differently */
	} else {
		for (i = C_BLK; i <= C_UND; ++i)
			init_pair(i, fcolors[i], -1);
		if (g_state.dirctx) {
			for (i = 0; i < CTX_MAX; ++i) {
				if (ctxcolor_set[i])
					init_pair(C_DIRCTX_BASE + i, g_ctx[i].color, -1);
				else
					init_pair(C_DIRCTX_BASE + i, -1, -1);
			}
		}
	}
	return true;
}

