/* ---------------- size formatting ---------------- */

static char *coolsize(off_t size)
{
	const char * const U = "BKMGTPEZY";
	static char size_buf[24];
	off_t rem = 0;
	size_t ret;
	int i = 0;

	while (size >= 1024) {
		rem = size & (0x3FF);
		size >>= 10;
		++i;
	}

	rem = (rem * 1000) >> 10;

	if (i == 1) {
		rem = (rem + 50) / 100;
		if (rem == 10) {
			++size;
			rem = 0;
		}
	} else if (i == 2) {
		rem = (rem + 5) / 10;
		if (rem == 100) {
			++size;
			rem = 0;
		}
	}

	if (i > 0 && rem) {
		int digits = i >= 3 ? 3 : i;
		ret = snprintf(size_buf, sizeof(size_buf), "%lld.%0*lld%c", (long long)size, digits, (long long)rem, U[i]);
	} else
		ret = snprintf(size_buf, sizeof(size_buf), "%lld%c", (long long)size, U[i]);
	(void)ret;
	return size_buf;
}

/* ---------------- sorting ---------------- */

static long long xatoll(const char *s)
{
	return strtoll(s, NULL, 10);
}

static int xstricmp(const char * const s1, const char * const s2)
{
	const char *c1 = s1, *c2 = s2;

	while (isspace((unsigned char)*c1))
		++c1;
	while (isspace((unsigned char)*c2))
		++c2;

	if (*c1 == '-' || *c1 == '+')
		++c1;
	if (*c2 == '-' || *c2 == '+')
		++c2;

	if (xisdigit(*c1) && xisdigit(*c2)) {
		long long d1 = xatoll(s1), d2 = xatoll(s2);
		if (d1 != d2)
			return d1 > d2 ? 1 : -1;
	} else if (xisdigit(*c1))
		return -1;
	else if (xisdigit(*c2))
		return 1;

	return strcoll(s1, s2);
}

/* Version comparison, case insensitive (strverscmp-like) */
#define S_N 0x0
#define S_I 0x3
#define S_F 0x6
#define S_Z 0x9
#define VCMP 2
#define VLEN 3

static int xstrverscasecmp(const char * const s1, const char * const s2)
{
	static const uint8_t next_state[] = {
		/* state    x    d    0  */
		/* S_N */  S_N, S_I, S_Z,
		/* S_I */  S_N, S_I, S_I,
		/* S_F */  S_N, S_F, S_F,
		/* S_Z */  S_N, S_F, S_Z
	};
	static const int8_t result_type[] = {
		/* state   x/x  x/d  x/0  d/x  d/d  d/0  0/x  0/d  0/0  */
		/* S_N */  VCMP, VCMP, VCMP, VCMP, VLEN, VCMP, VCMP, VCMP, VCMP,
		/* S_I */  VCMP,   -1,   -1,   +1, VLEN, VLEN,   +1, VLEN, VLEN,
		/* S_F */  VCMP, VCMP, VCMP, VCMP, VCMP, VCMP, VCMP, VCMP, VCMP,
		/* S_Z */  VCMP,   +1,   +1,   -1, VCMP, VCMP,   -1, VCMP, VCMP
	};
	const uchar_t *p1 = (const uchar_t *)s1, *p2 = (const uchar_t *)s2;
	uchar_t c1, c2;
	int state, diff;

	if (p1 == p2)
		return 0;

	c1 = TOUPPER(*p1);
	++p1;
	c2 = TOUPPER(*p2);
	++p2;

	state = S_N + ((c1 == '0') + (xisdigit(c1) != 0));

	while ((diff = c1 - c2) == 0) {
		if (c1 == '\0')
			return diff;
		state = next_state[state];
		c1 = TOUPPER(*p1);
		++p1;
		c2 = TOUPPER(*p2);
		++p2;
		state += (c1 == '0') + (xisdigit(c1) != 0);
	}

	state = result_type[state * 3 + (((c2 == '0') + (xisdigit(c2) != 0)))];

	switch (state) {
	case VCMP:
		return diff;
	case VLEN:
		while (xisdigit(*p1++))
			if (!xisdigit(*p2++))
				return 1;
		return xisdigit(*p2) ? -1 : diff;
	default:
		return state;
	}
}

static int (*namecmpfn)(const char * const s1, const char * const s2) = &xstricmp;

static int entrycmp(const void *va, const void *vb)
{
	const struct entry *pa = (const struct entry *)va;
	const struct entry *pb = (const struct entry *)vb;

	if ((pb->flags & DIR_OR_DIRLNK) != (pa->flags & DIR_OR_DIRLNK)) {
		if (pb->flags & DIR_OR_DIRLNK)
			return 1;
		return -1;
	}

	/* Sort based on specified order */
	if (cfg.timeorder) {
		if (pb->sec > pa->sec)
			return 1;
		if (pb->sec < pa->sec)
			return -1;
		/* If sec matches, comare nsec */
		if (pb->nsec > pa->nsec)
			return 1;
		if (pb->nsec < pa->nsec)
			return -1;
	} else if (cfg.sizeorder) {
		if (pb->size > pa->size)
			return 1;
		if (pb->size < pa->size)
			return -1;
	} else if (cfg.blkorder) {
		if (pb->blocks > pa->blocks)
			return 1;
		if (pb->blocks < pa->blocks)
			return -1;
	} else if (cfg.extnorder && !(pb->flags & DIR_OR_DIRLNK)) {
		char *extna = xextension(pa->name, pa->nlen - 1);
		char *extnb = xextension(pb->name, pb->nlen - 1);

		if (extna || extnb) {
			if (!extna)
				return -1;
			if (!extnb)
				return 1;
			int res = strcasecmp(extna, extnb);
			if (res)
				return res;
		}
	}

	return namecmpfn(pa->name, pb->name);
}

static int reventrycmp(const void *va, const void *vb)
{
	if ((((const struct entry *)vb)->flags & DIR_OR_DIRLNK)
	    != (((const struct entry *)va)->flags & DIR_OR_DIRLNK)) {
		if (((const struct entry *)vb)->flags & DIR_OR_DIRLNK)
			return 1;
		return -1;
	}
	return -entrycmp(va, vb);
}

static int (*entrycmpfn)(const void *va, const void *vb) = &entrycmp;

static void sort_entries(void)
{
	if (ndents > 1)
		qsort(pdents, ndents, sizeof(*pdents), entrycmpfn);
}

