actions.command:
cat >> /workspace/src/nnn.c <<'EOF'

/* ---------------- entry display ---------------- */

static char get_ind(mode_t mode, bool perms)
{
	switch (mode & S_IFMT) {
	case S_IFREG:
		if (perms)
			return '-';
		if (mode & 0100)
			return '*';
		return '\0';
	case S_IFDIR:
		return perms ? 'd' : '/';
	case S_IFLNK:
		return perms ? 'l' : '@';
	case S_IFSOCK:
		return perms ? 's' : '=';
	case S_IFIFO:
		return perms ? 'p' : '|';
	case S_IFBLK:
		return perms ? 'b' : '\0';
	case S_IFCHR:
		return perms ? 'c' : '\0';
	default:
		return '?';
	}
}

static char *get_lsperms(mode_t mode)
{
	static const char * const rwx[] = {"---", "--x", "-w-", "-wx", "r--", "r-x", "rw-", "rwx"};
	static char bits[11] = {'\0'};

	bits[0] = get_ind(mode, true);

	xstrsncpy(&bits[1], rwx[(mode >> 6) & 7], 4);
	xstrsncpy(&bits[4], rwx[(mode >> 3) & 7], 4);
	xstrsncpy(&bits[7], rwx[(mode & 7)], 4);

	if (mode & S_ISUID)
		bits[3] = (mode & 0100) ? 's' : 'S';  /* user executable */
	if (mode & S_ISGID)
		bits[6] = (mode & 0010) ? 's' : 'l';  /* group executable */
	if (mode & S_ISVTX)
		bits[9] = (mode & 0001) ? 't' : 'T';  /* others executable */

	return bits;
}

static uchar_t get_color_pair_name_ind(const struct entry *ent, char *pind, int *pattr)
{
	switch (ent->mode & S_IFMT) {
	case S_IFREG:
		if (!ent->size) {
			if (ent->mode & 0100)
				*pind = '*';
			return C_UND;
		}
		if (ent->flags & HARD_LINK) {
			if (ent->mode & 0100)
				*pind = '*';
			return C_HRD;
		}
		if (ent->mode & 0100) {
			*pind = '*';
			return C_EXE;
		}
		return C_FIL;
	case S_IFDIR:
		*pind = '/';
		if (g_state.oldcolor)
			return C_DIR;
		*pattr |= A_BOLD;
		return (g_state.dirctx ? C_DIRCTX_BASE + cfg.curctx : C_DIR);
	case S_IFLNK:
		if (ent->flags & DIR_OR_DIRLNK) {
			*pind = '/';
			*pattr |= g_state.oldcolor ? A_DIM : A_BOLD;
		} else {
			*pind = '@';
			if (g_state.oldcolor)
				*pattr |= A_DIM;
		}
		if (!g_state.oldcolor || cfg.showdetail)
			return (ent->flags & SYM_ORPHAN) ? C_ORP : C_LNK;
		return 0;
	case S_IFSOCK:
		*pind = '=';
		return C_SOC;
	case S_IFIFO:
		*pind = '|';
		return C_PIP;
	case S_IFBLK:
		return C_BLK;
	case S_IFCHR:
		return C_CHR;
	}

	*pind = '?';
	return C_UND;
}

/* Convert a name into a wide string, dropping unprintable chars; truncate to maxcols */
static wchar_t *unescape(const char *str, uint_t maxcols)
{
	wchar_t * const wbuf = (wchar_t *)g_buf;
	wchar_t *buf = wbuf;
	size_t lencount = 0;
	size_t len = mbstowcs(wbuf, str, maxcols);

	if (len != (size_t)-1) {
		wbuf[len] = L'\0';
		/* Reduce number of wide chars to max columns */
		{
			int w = 0;
			size_t i;
			for (i = 0; i < len; ++i) {
				int cw = wcwidth(wbuf[i]);
				if (cw < 0)
					cw = 0;
				if (w + cw > (int)maxcols) {
					wbuf[i] = L'\0';
					break;
				}
				w += cw;
			}
		}
	} else {
		/* conversion failed, buffer holds partial conversion and stale content */
		wbuf[maxcols] = L'\0';
	}

	while (*buf) {
		if (!iswprint(*buf))
			*buf = L'\0';
		++buf;
		++lencount;
	}
	(void)lencount;
	return wbuf;
}

static char *get_time_str(time_t sec)
{
	static char buf[24];
	struct tm *t = localtime(&sec);
	if (!t || !strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M", t))
		buf[0] = '\0';
	return buf;
}

static bool youngfile(const struct entry *ent)
{
	return (ent->flags & FILE_YOUNG);
}

static void print_time(const struct entry *ent, int attrs)
{
	bool young = youngfile(ent);
	if (young)
		attron(A_REVERSE);
	addstr(get_time_str(ent->sec));
	if (young)
		attroff(A_REVERSE);
}

static void print_details(const struct entry *ent, int attrs)
{
	int ind;
	char ind_c = '\0';
	int dummy = 0;

	(void)attrs;
	ind = get_color_pair_name_ind(ent, &ind_c, &dummy);
	(void)ind;

	/* Timestamp */
	print_time(ent, 0);

	/* Permissions */
	printw("  %03o", ent->mode & 0777);

