	switch (ent->mode & S_IFMT) {
	case S_IFREG:
	case S_IFDIR:
		printw("%9s", coolsize(cfg.blkorder ? (off_t)ent->blocks << 9 : ent->size));
		break;
	case S_IFLNK:
		printw("%9c", '@');
		break;
	case S_IFSOCK:
		printw("%9c", '=');
		break;
	case S_IFIFO:
		printw("%9c", '|');
		break;
	case S_IFBLK:
		printw("%9c", 'b');
		break;
	case S_IFCHR:
		printw("%9c", 'c');
		break;
	default:
		printw("%9c", '?');
		break;
	}
	addch(' ');
}

static void printent(const struct entry *ent, uint_t namecols, bool sel)
{
	char ind = '\0';
	int attrs = 0;
	uchar_t pair;
	bool color = coloriseentries();

	pair = get_color_pair_name_ind(ent, &ind, &attrs);

	if (cfg.showdetail) {
		if (sel)
			addch('>' | A_BOLD);
		else
			addch(' ');

		if (color) {
			if (g_state.oldcolor)
				attron(A_DIM);
			else
				attron(COLOR_PAIR(C_MIS));
		}
		print_details(ent, 0);
		if (color) {
			if (g_state.oldcolor)
				attroff(A_DIM);
			else
				attroff(COLOR_PAIR(C_MIS));
		}
	}

	addch((ent->flags & FILE_SELECTED) ? ('+' | A_REVERSE | A_BOLD) : ' ');

