	if (g_state.oldcolor && S_ISDIR(ent->mode) && sel)
		attrs |= A_BOLD;

	if (ind)
		--namecols;

	if (attrs)
		attron(attrs);
	addwstr(unescape(ent->name, namecols));
	if (attrs)
		attroff(attrs);

	if (ind)
		addch(ind);

	if (g_state.oldcolor && (ent->flags & DIR_OR_DIRLNK) && S_ISDIR(ent->mode) && color)
		attroff(COLOR_PAIR(C_CTX_BASE + cfg.curctx));
}

