{"command":"cat >> /workspace/src/nnn.c <<'EOF'

/* ---------------- header ---------------- */

static int adjust_cols(int n)
{
	/* Calculate the number of cols available to print entry name */
	if (cfg.showdetail) {
		/* Fallback to light mode if less than 35 columns */
		if (n < 36)
			cfg.showdetail ^= 1;
		else /* 2 more accounted for below */
			n -= 31;
	}

	/* 2 columns for preceding space and indicator */
	return (n - 2);
}

static void draw_line(int ncols)
{
	bool dir = false;

	ncols = adjust_cols(ncols);

	if (pdents[last_curscroll].flags & DIR_OR_DIRLNK) {
		attron(COLOR_PAIR(C_CTX_BASE + cfg.curctx) | A_BOLD);
		dir = true;
	}
	(void)dir;
}

static void print_path(char *path, int maxlen)
{
	/* Print path with ~ for home; abbreviate components if it does not fit */
	char buf[PATH_MAX_LEN];
	char *p = path;
	size_t hlen = homedir ? strlen(homedir) : 0;
	int len;

	if (homedir && hlen > 1 && is_prefix(path, homedir, hlen) && (path[hlen] == '\0' || path[hlen] == '/')) {
		buf[0] = '~';
		xstrsncpy(buf + 1, path + hlen, PATH_MAX_LEN - 1);
	} else
		xstrsncpy(buf, path, PATH_MAX_LEN);

	len = (int)mbstowcs(NULL, buf, 0);
	if (len < 0)
		len = (int)strlen(buf);

	if (len > maxlen) {
		/* abbreviate all but the last component */
		char out[PATH_MAX_LEN];
		char *base = strrchr(buf, '/');
		size_t o = 0;
		p = buf;
		if (base) {
			while (p < base) {
				if (*p == '/') {
					out[o++] = '/';
					++p;
					if (p < base && *p) {
						/* copy one (multibyte) char */
						int clen = mblen(p, MB_CUR_MAX);
						if (clen <= 0)
							clen = 1;
						memcpy(out + o, p, clen);
						o += clen;
						p += clen;
						while (p < base && *p != '/')
							++p;
					}
				} else {
					int clen = mblen(p, MB_CUR_MAX);
					if (clen <= 0)
						clen = 1;
					memcpy(out + o, p, clen);
					o += clen;
					p += clen;
					while (p < base && *p != '/')
						++p;
				}
			}
			xstrsncpy(out + o, base, PATH_MAX_LEN - o);
		} else
			xstrsncpy(out, buf, PATH_MAX_LEN);
		xstrsncpy(buf, out, PATH_MAX_LEN);
	}

	/* print at most maxlen columns */
	{
		wchar_t *w = (wchar_t *)g_buf;
		size_t wl = mbstowcs(w, buf, CMD_LEN_MAX / sizeof(wchar_t) - 1);
		if (wl == (size_t)-1) {
			addnstr(buf, maxlen);
		} else {
			int width = 0;
			size_t i;
			w[wl] = L'\0';
			for (i = 0; i < wl; ++i) {
				int cw = wcwidth(w[i]);
				if (cw < 0)
					cw = 1;
				if (width + cw > maxlen) {
					w[i] = L'\0';
					break;
				}
				width += cw;
			}
			addwstr(w);
		}
	}
}

static void print_header(char *path)
{
	int i, attrs;

	move(0, 0);
	for (i = 0; i < CTX_MAX; ++i) {
		if (i == (int)cfg.curctx) {
			attrs = COLOR_PAIR(C_CTX_BASE + i) | A_BOLD | A_REVERSE;
			attron(attrs);
			addch('1' + i);
			attroff(attrs);
		} else if (g_ctx[i].c_cfg.ctxactive) {
			attrs = COLOR_PAIR(C_CTX_BASE + i) | A_BOLD | A_UNDERLINE;
			attron(attrs);
			addch('1' + i);
			attroff(attrs);
		} else
			addch('1' + i);
		addch(' ');
	}

	attrs = COLOR_PAIR(C_CTX_BASE + cfg.curctx) | A_UNDERLINE;
	attron(attrs);
	print_path(path, xcols - (CTX_MAX * 2));
	attroff(attrs);
}

/* ---------------- redraw ---------------- */

static void redraw(char *path)
{
	int ncols, i, onscreen;

	getmaxyx(stdscr, xlines, xcols);
	onscreen = xlines - 4;

	/* Clamp scroll */
	if (ndents <= onscreen)
		curscroll = 0;
	else {
		curscroll = MIN(curscroll, MIN(cur, ndents - onscreen));
		curscroll = MAX(curscroll, MAX(cur - (onscreen - 1), 0));
	}
	last_curscroll = curscroll;

	erase();

	print_header(path);

	if (curscroll > 0) {
		move(1, 0);
		addch('^');
	}

	ncols = adjust_cols(xcols);

	for (i = curscroll; i < ndents && i < curscroll + onscreen; ++i) {
		move(2 + i - curscroll, 0);
		printent(&pdents[i], ncols, i == cur);
	}

	if (ndents > onscreen && curscroll + onscreen < ndents) {
		move(xlines - 2, 0);
		addch('v');
	}

	statusbar(path);
}
EOF
echo ok"}

