						if (clen <= 0)
							clen = 1;
						memcpy(out + o, p, clen);
						o += clen;
						p += clen;
						while (p < base && *p != '/')
							++p;
					}
				} else {
					int clen = mblen(p, MB_CUR_MAX);
					if (clen <= 0)
						clen = 1;
					memcpy(out + o, p, clen);
					o += clen;
					p += clen;
					while (p < base && *p != '/')
						++p;
				}
			}
			xstrsncpy(out + o, base, PATH_MAX_LEN - o);
		} else
			xstrsncpy(out, buf, PATH_MAX_LEN);
		xstrsncpy(buf, out, PATH_MAX_LEN);
	}

	/* print at most maxlen columns */
	{
		wchar_t *w = (wchar_t *)g_buf;
		size_t wl = mbstowcs(w, buf, CMD_LEN_MAX / sizeof(wchar_t) - 1);
		if (wl == (size_t)-1) {
			addnstr(buf, maxlen);
		} else {
			int width = 0;
			size_t i;
			w[wl] = L'\0';
			for (i = 0; i < wl; ++i) {
				int cw = wcwidth(w[i]);
				if (cw < 0)
					cw = 1;
				if (width + cw > maxlen) {
					w[i] = L'\0';
					break;
				}
				width += cw;
			}
			addwstr(w);
		}
	}
}

static void print_header(char *path)
{
	int i, attrs;

	move(0, 0);
	for (i = 0; i < CTX_MAX; ++i) {
		if (i == (int)cfg.curctx) {
			attrs = COLOR_PAIR(C_CTX_BASE + i) | A_BOLD | A_REVERSE;
			attron(attrs);
			addch('1' + i);
			attroff(attrs);
		} else if (g_ctx[i].c_cfg.ctxactive) {
			attrs = COLOR_PAIR(C_CTX_BASE + i) | A_BOLD | A_UNDERLINE;
			attron(attrs);
			addch('1' + i);
			attroff(attrs);
		} else
			addch('1' + i);
		addch(' ');
	}

	attrs = COLOR_PAIR(C_CTX_BASE + cfg.curctx) | A_UNDERLINE;
	attron(attrs);
	print_path(path, xcols - (CTX_MAX * 2));
	attroff(attrs);
}

/* ---------------- redraw ---------------- */

static void redraw(char *path)
{
	int ncols, i, onscreen;

	getmaxyx(stdscr, xlines, xcols);
	onscreen = xlines - 4;

	/* Clamp scroll */
	if (ndents <= onscreen)
		curscroll = 0;
	else {
		curscroll = MIN(curscroll, MIN(cur, ndents - onscreen));
		curscroll = MAX(curscroll, MAX(cur - (onscreen - 1), 0));
	}
	last_curscroll = curscroll;

	erase();

	print_header(path);

	if (curscroll > 0) {
		move(1, 0);
		addch('^');
	}

	ncols = adjust_cols(xcols);

	for (i = curscroll; i < ndents && i < curscroll + onscreen; ++i) {
		move(2 + i - curscroll, 0);
		printent(&pdents[i], ncols, i == cur);
	}

	if (ndents > onscreen && curscroll + onscreen < ndents) {
		move(xlines - 2, 0);
		addch('v');
	}

	statusbar(path);
}
