			dentp->nsec = sb.st_mtim.tv_nsec;
			break;
		}

		if ((curtime - sb.st_mtime) < YOUNG_SECS || (curtime - sb.st_ctime) < YOUNG_SECS)
			entflags |= FILE_YOUNG;

		if (cfg.blkorder || cfg.apparentsz) {
			if (S_ISDIR(sb.st_mode)) {
