		if (S_ISLNK(sb.st_mode)) {
			struct stat tsb;
			dentp->size = sb.st_size;
			if (fstatat(fd, namep, &tsb, 0) == -1) {
				entflags |= SYM_ORPHAN;
				/* keep lstat info */
			} else {
				if (S_ISDIR(tsb.st_mode))
					entflags |= DIR_OR_DIRLNK;
				tsb.st_mode = (tsb.st_mode & ~S_IFMT) | S_IFLNK;
				tsb.st_size = sb.st_size;
				sb = tsb;
			}
		} else {
			dentp->size = sb.st_size;
			if (S_ISDIR(sb.st_mode))
				entflags |= DIR_OR_DIRLNK;
			else if (S_ISREG(sb.st_mode) && sb.st_nlink > 1)
				entflags |= HARD_LINK;
		}

		dentp->mode = sb.st_mode;
		dentp->uid = sb.st_uid;
		dentp->gid = sb.st_gid;
		dentp->blocks = sb.st_blocks;

		switch (cfg.timetype) {
		case T_ACCESS:
			dentp->sec = sb.st_atime;
			dentp->nsec = sb.st_atim.tv_nsec;
			break;
		case T_CHANGE:
			dentp->sec = sb.st_ctime;
			dentp->nsec = sb.st_ctim.tv_nsec;
			break;
		default:
			dentp->sec = sb.st_mtime;
			dentp->nsec = sb.st_mtim.tv_nsec;
			break;
		}

		if ((curtime - sb.st_mtime) < YOUNG_SECS || (curtime - sb.st_ctime) < YOUNG_SECS)
			entflags |= FILE_YOUNG;

		if (cfg.blkorder || cfg.apparentsz) {
			if (S_ISDIR(sb.st_mode)) {
				ent_blocks = 0;
				mkpath(path, namep, buf);

				if (sb_path.st_dev == sb.st_dev) {
					nftw(buf, cfg.apparentsz ? sum_asize : sum_bsize, 20, FTW_MOUNT | FTW_PHYS);
					if (cfg.apparentsz)
						dentp->size = ent_blocks;
					else
						dentp->blocks = ent_blocks;
				} else {
					if (cfg.apparentsz)
						dentp->size = sb.st_size;
					else
						dentp->blocks = sb.st_blocks;
				}
				dir_blocks += (cfg.apparentsz ? dentp->size : dentp->blocks);
			} else {
				dir_blocks += (cfg.apparentsz ? sb.st_size : sb.st_blocks);
			}
			++num_files;
		}

		/* selection */
		{
			size_t plen = mkpath(path, namep, g_buf);
			if (pselbuf && selbufpos) {
				/* check if path is in selection */
				size_t pos = 0;
				while (pos < selbufpos) {
					size_t l = strlen(pselbuf + pos);
					if (l == plen - 1 && !strcmp(pselbuf + pos, g_buf)) {
						entflags |= FILE_SELECTED;
						break;
					}
					pos += l + 1;
				}
			}
		}

		dentp->flags = entflags;
		++n;
	}

exit:
	closedir(dirp);
	(void)flags;
	return n;
}

static bool ftw_fn_init_done(void) { return true; }
