static int inotify_poll(void)
{
	char buf[4096];
	struct pollfd pfd = { .fd = inotify_fd, .events = POLLIN };
	int got = 0;

	if (inotify_fd < 0)
		return 0;
	while (poll(&pfd, 1, 0) > 0 && (pfd.revents & POLLIN)) {
		ssize_t r = read(inotify_fd, buf, sizeof(buf));
		if (r <= 0)
			break;
		got = 1;
	}
	return got;
}

static void inotify_set(const char *path)
{
	if (inotify_fd < 0)
		return;
	if (inotify_wd >= 0) {
		inotify_rm_watch(inotify_fd, inotify_wd);
		inotify_wd = -1;
	}
	inotify_wd = inotify_add_watch(inotify_fd, path,
		IN_ATTRIB | IN_CREATE | IN_DELETE | IN_DELETE_SELF | IN_MODIFY | IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO);
}

static int g_altkey;

/* read a key; returns ERR on timeout; handles Alt-prefixed keys */
static int getkey(int wait_ms)
{
	int c;

	timeout(wait_ms);
	c = getch();
	g_altkey = 0;
	if (c == 27) {
		timeout(0);
		int c2 = getch();
		timeout(wait_ms);
		if (c2 != ERR) {
			g_altkey = 1;
			return c2;
		}
		return 27;
	}
	return c;
}

static int nextsel(int presel)
{
	int c = presel;
	uint_t i;
	bool escaped = false;

	if (c == 0 || c == MSGWAIT) {
		int wait = (c == MSGWAIT) ? 1000 : 1000;
		for (;;) {
			c = getkey(wait);
			if (c == ERR) {
				++idle;
				if (presel == MSGWAIT) {
					/* message timed out: redraw status */
					return SEL_REDRAW;
				}
				if (inotify_poll())
					return SEL_REDRAW; /* refresh */
				if (idletimeout && idle >= idletimeout) {
					idle = 0;
					return SEL_LOCK;
				}
				continue;
			}
			idle = 0;
			break;
		}
		if (c == 27) {
			/* Esc: check for second Esc */
			int c2 = getkey(500);
			if (c2 == 27 && !g_altkey)
				return SEL_QUIT;
			if (c2 == ERR) {
				return SEL_FIFO;
			}
			if (g_altkey) {
				/* Alt+Esc */
				if (c2 == 27)
					return SEL_UNFLTRQUIT;
			}
			/* Esc followed by another key: treat the other key as Alt-key */
			g_altkey = 1;
			c = c2;
			escaped = true;
		}
	}

	if (g_altkey || escaped) {
		if (c == ';')
			return SEL_PLUGIN;
		if (c == 27)
			return SEL_UNFLTRQUIT;
		/* Alt + key: plugin hotkey */
		g_altkey = c;
		return SEL_PLUGKEY;
	}

	if (c == KEY_RESIZE)
		return SEL_REDRAW;

	for (i = 0; bindings[i].sym; ++i)
		if (c == bindings[i].sym)
			return bindings[i].act;

	return 0;
}
