/* Partition entries matching the filter to the front; returns count, -1 on error */
static int fill(const char *fltr)
{
	int count = 0;

	if (!setfilter_compile(fltr))
		return -1;

	for (int i = 0; i < ndents; ++i) {
		if (visible_entry(pdents[i].name, fltr)) {
			if (count != i) {
				struct entry tmp = pdents[count];
				pdents[count] = pdents[i];
				pdents[i] = tmp;
			}
			++count;
		}
	}
	return count;
}

static int matches(const char *fltr)
{
	int n = fill(fltr);

	if (n == -1)
		return -1;
	ndents = n;
	sort_entries();
	return ndents;
}

static int filterentries(char *path, char *lastname_)
{
	wchar_t *wln = (wchar_t *)malloc(sizeof(wchar_t) * (NAME_MAX_LEN + 2));
	char *ln = g_ctx[cfg.curctx].c_fltr;
	wint_t ch[1] = {0};
	int r, total = ndents, len;
	char *pln = ln + 1;
	bool exit_on_key = false;

	if (!wln)
		return 0;

	if ((ln[0] == FILTER || ln[0] == RFILTER) && *pln) {
		if (matches(pln) != -1) {
			move_cursor(dentfind(lastname_, ndents), 0);
			redraw(path);
		}
		len = (int)mbstowcs(wln, ln, NAME_MAX_LEN);
		if (len < 0)
			len = 1;
	} else {
		ln[0] = (flt_type == FLT_REG) ? RFILTER : FILTER;
		wln[0] = (wchar_t)ln[0];
		ln[1] = '\0';
		wln[1] = L'\0';
		len = 1;
	}

	curs_set(TRUE);
	showfilter(ln);
	timeout(-1);

	while ((r = get_wch(ch)) != ERR) {
		switch (*ch) {
		case KEY_DC:
		case KEY_BACKSPACE:
		case '\b':
		case 127:
			if (len != 1) {
				wln[--len] = L'\0';
				wcstombs(ln, wln, NAME_MAX_LEN);
				ndents = total;
				if (matches(pln) != -1) {
					cur = 0;
					redraw(path);
				}
				showfilter(ln);
			}
			continue;
		case 27: /* Esc */
			{
				/* Alt+key? */
				timeout(0);
				int c2 = getch();
				timeout(-1);
				if (c2 == 27) {
					*ch = KEY_F(63); /* Alt+Esc marker */
					goto end;
				}
				if (c2 != ERR) {
					g_altkey = c2;
					*ch = KEY_F(62); /* Alt+key marker */
					goto end;
				}
			}
			goto end;
		}

		if (r == OK) {
			/* Handle all control chars in main loop */
			if (*ch < 128 && ((*ch < 32 && *ch != '\t') || *ch == 127)) {
				if (*ch == 0)
					*ch = 'm';
				goto end;
			}

			if (len == 1) {
				if (*ch == '?') /* Help and config key, '?' is not a regex */
					goto end;

				if (cfg.filtermode) {
					switch (*ch) {
					case '\'':
					case '+':
					case ',':
					case '-':
					case '.':
					case ';':
					case '=':
					case '>':
					case '@':
					case ']':
					case '`':
					case '~':
						goto end;
					}
				}

				/* Toggle filter type */
				if (*ch == FILTER) {
					flt_type = (flt_type + 1) % 3;
					ln[0] = (flt_type == FLT_REG) ? RFILTER : FILTER;
					wln[0] = (wchar_t)ln[0];
					showfilter(ln);
					continue;
				}

				if (*ch == ':') {
					flt_icase = !flt_icase;
					showfilter(ln);
					continue;
				}
			}

			/* Reset cur in case it's a repeat search */
			if (len == 1)
				cur = 0;

			if (len == NAME_MAX_LEN - 1)
				break;

			wln[len] = (wchar_t)*ch;
			wln[++len] = L'\0';
			wcstombs(ln, wln, NAME_MAX_LEN);

			/* new matches can only be a subset of current matches */
			if (matches(pln) == -1) {
				showfilter(ln);
				continue;
			}

			cur = 0;

			/* If the only match is a dir, auto-select and cd into it */
			if (ndents == 1 && cfg.autoenter && (pdents[0].flags & DIR_OR_DIRLNK)) {
				*ch = KEY_ENTER;
				cur = 0;
				goto end;
			}

			redraw(path);
			showfilter(ln);
		} else {
			/* function keys etc. handled by main loop */
			exit_on_key = true;
			goto end;
		}
	}
end:
	(void)exit_on_key;
	/* Save last working filter in-filter */
	if (ln[1])
		xstrsncpy(last_filter, ln + 1, NAME_MAX_LEN + 1);

	/* Save current */
	if (ndents)
		xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);

	curs_set(FALSE);
	timeout(1000);
	free(wln);

	return *ch;
}
