			"NNN_TMPFILE", "NNN_MCLICK", "NNN_ARCHMNT", "NNN_SSHFS", "NNN_RCLONE", NULL};
		bool first = true;
		for (int i = 0; envs[i]; ++i) {
			char *v = getenv(envs[i]);
			if (v) {
				if (first) {
					fputs("\nCONFIGURATION\n", fp);
					first = false;
				}
				fprintf(fp, " %s: %s\n", envs[i], v);
			}
		}
	}

