		xstrsncpy(cmd, archive_cmd[3], 16);
}

static void archive_selection(const char *cmd, const char *archive, const char *curpath)
{
	/* build argv: cmd words, archive, then all selected paths */
	char *argv[4096];
	int n = 0;
	char cmdbuf[32];
	char *p, *saveptr;
	size_t pos = 0;

	xstrsncpy(cmdbuf, cmd, sizeof(cmdbuf));
	for (p = strtok_r(cmdbuf, " ", &saveptr); p; p = strtok_r(NULL, " ", &saveptr))
		argv[n++] = p;
	argv[n++] = (char *)archive;
	while (pos < selbufpos && n < 4090) {
		argv[n++] = pselbuf + pos;
		pos += strlen(pselbuf + pos) + 1;
	}
	argv[n] = NULL;

	exitcurses();
	{
		pid_t pid = xfork(F_NORMAL);
		if (pid == 0) {
			if (chdir(curpath) == -1) {}
			execvp(argv[0], argv);
			_exit(EXIT_FAILURE);
		}
		join(pid, F_NORMAL);
	}
	refresh();
}

/* Run a command (space separated words) with arguments on all selected paths */
static int run_on_selection(const char *cmdwords, const char *extra_last, ushort flag)
{
	char *argv[4096];
	int n = 0;
	char cmdbuf[64];
	char *p, *saveptr;
	size_t pos = 0;
	pid_t pid;
	int status;

	xstrsncpy(cmdbuf, cmdwords, sizeof(cmdbuf));
	for (p = strtok_r(cmdbuf, " ", &saveptr); p; p = strtok_r(NULL, " ", &saveptr))
		argv[n++] = p;
	while (pos < selbufpos && n < 4090) {
		argv[n++] = pselbuf + pos;
		pos += strlen(pselbuf + pos) + 1;
	}
	if (extra_last)
		argv[n++] = (char *)extra_last;
	argv[n] = NULL;

	if (flag & F_NORMAL)
		exitcurses();
	pid = xfork(flag);
	if (pid == 0) {
		if (flag & F_NOTRACE) {
			int fd = open("/dev/null", O_WRONLY);
			dup2(fd, STDOUT_FILENO);
			dup2(fd, STDERR_FILENO);
			close(fd);
		}
		execvp(argv[0], argv);
		_exit(EXIT_FAILURE);
	}
	status = join(pid, flag);
	if (flag & F_NORMAL)
		refresh();
	return status;
}

static bool rmmulstr(char *buf, bool use_trash)
{
	(void)buf;
	if (!use_trash) {
		char prompt[64];
		snprintf(prompt, sizeof(prompt), "rm -rf %d file(s)?", selbufcount());
		if (!xconfirm(get_input(prompt)))
			return false;
		run_on_selection("rm -fvr --", NULL, F_NORMAL);
	} else {
		run_on_selection(g_state.trash == 1 ? "trash-put" : "gio trash", NULL, F_NORMAL);
	}
	return true;
}

static bool xrm(char * const fpath, bool use_trash)
{
	if (!use_trash) {
		char prompt[NAME_MAX_LEN + 32];
		snprintf(prompt, sizeof(prompt), "rm -rf '%s'?", xbasename(fpath));
		if (!xconfirm(get_input(prompt)))
			return false;
		spawn("rm", "-vrf", "--", fpath, F_NORMAL);
	} else {
		if (g_state.trash == 1)
			spawn("trash-put", fpath, NULL, NULL, F_NORMAL);
		else
			spawn("gio", "trash", fpath, NULL, F_NORMAL);
	}
	return access(fpath, F_OK) != 0;
}

/* Read a file of NUL/newline separated paths into the selection buffer */
static bool selbuf_from_file(const char *fpath, bool nulsep)
{
	int fd = open(fpath, O_RDONLY);
	struct stat sb;
	char *buf;
	ssize_t n;

	if (fd == -1)
		return false;
	if (fstat(fd, &sb) == -1 || sb.st_size == 0) {
		close(fd);
		return false;
	}
	buf = malloc(sb.st_size + 1);
	if (!buf) {
		close(fd);
		return false;
	}
	n = read(fd, buf, sb.st_size);
	close(fd);
	if (n <= 0) {
		free(buf);
		return false;
	}
	buf[n] = '\0';

	selbufpos = 0;
	nselected = 0;
	{
		char *p = buf, *end = buf + n;
		while (p < end) {
			char *q = p;
			if (nulsep) {
				while (q < end && *q)
					++q;
			} else {
				while (q < end && *q != '\n')
					++q;
			}
			*q = '\0';
			if (*p) {
				appendfpath(p, strlen(p) + 1);
				++nselected;
			}
			p = q + 1;
		}
	}
	free(buf);
	return selbufpos > 0;
}

/* Open editor with the selection list to let the user enter paths */
static bool edit_selection_paths(void)
{
	int fd = create_tmp_file();
	if (fd == -1)
		return false;
	close(fd);
	run_editor(g_tmpfpath);
	selbuf_from_file(g_tmpfpath, false);
	unlink(g_tmpfpath);
	return selbufpos > 0;
}

/* cp/mv selection to current dir */
static bool cpmv_selection(bool move, char *curpath)
{
	if (!selbufpos) {
		/* allow pasting paths into an editor */
		if (!edit_selection_paths()) {
			printmsg("0 selected");
			return false;
		}
	}

	if (move)
		run_on_selection("mv -i --", ".", F_NORMAL);
	else
		run_on_selection("cp -iRp --", ".", F_NORMAL);

	(void)curpath;
	clearselection();
	return true;
}

/* cp/mv as: edit destination names */
static bool cpmv_as(bool move, char *curpath)
{
	int fd;
	FILE *fp;
	size_t pos = 0;
	char **srcs = NULL;
	int nsrc = 0;

	if (!selbufpos)
		return false;

	fd = create_tmp_file();
	if (fd == -1)
		return false;
	fp = fdopen(fd, "w");
	if (!fp) {
		close(fd);
		return false;
	}
	while (pos < selbufpos) {
		fprintf(fp, "%s\n", xbasename(pselbuf + pos));
		srcs = xrealloc(srcs, (nsrc + 1) * sizeof(char *));
		srcs[nsrc++] = pselbuf + pos;
		pos += strlen(pselbuf + pos) + 1;
	}
	fclose(fp);

	run_editor(g_tmpfpath);

	/* read back names */
	fp = fopen(g_tmpfpath, "r");
	if (fp) {
		char line[PATH_MAX_LEN];
		int i = 0;
		char **dsts = calloc(nsrc, sizeof(char *));
		while (i < nsrc && fgets(line, sizeof(line), fp)) {
			size_t l = strlen(line);
			while (l && (line[l - 1] == '\n' || line[l - 1] == '\r'))
				line[--l] = '\0';
			dsts[i++] = strdup(line);
		}
		fclose(fp);
		if (i != nsrc) {
			printmsg("Error");
		} else {
			for (int k = 0; k < nsrc; ++k) {
				char dst[PATH_MAX_LEN];
				if (!dsts[k] || !*dsts[k])
					continue;
				mkpath(curpath, dsts[k], dst);
				if (move)
					spawn("mv", "-i", "--", NULL, F_NORMAL); /* placeholder replaced below */
				(void)dst;
			}
			/* actual execution with 4 args */
			for (int k = 0; k < nsrc; ++k) {
				char dst[PATH_MAX_LEN];
				if (!dsts[k] || !*dsts[k])
					continue;
				mkpath(curpath, dsts[k], dst);
				{
					char *argv[6] = { move ? "mv" : "cp", move ? "-i" : "-iRp", "--", srcs[k], dst, NULL };
					exitcurses();
					pid_t pid = xfork(F_NORMAL);
					if (pid == 0) {
						execvp(argv[0], argv);
						_exit(EXIT_FAILURE);
					}
					join(pid, F_NORMAL);
					refresh();
				}
			}
		}
		for (int k = 0; k < nsrc; ++k)
			free(dsts[k]);
		free(dsts);
	}
	free(srcs);
	unlink(g_tmpfpath);
	clearselection();
	return true;
}

