				fifopath = NULL;
			return;
		}
	}

	static struct entry lastentry;

	if (!force && !memcmp(&lastentry, &pdents[cur], sizeof(struct entry)))
		return;

	lastentry = pdents[cur];

	char fpath[PATH_MAX_LEN];
	size_t len;

	if (ndents)
		len = mkpath(path, pdents[cur].name, fpath);
	else {
		len = xstrsncpy(fpath, path, PATH_MAX_LEN);
		fpath[len - 1] = '\n';
		fpath[len] = '\0';
		++len;
	}
	fpath[len - 1] = '\n';

	ssize_t ret = write(fifofd, fpath, len);

	if (ret != (ssize_t)len && !(ret == -1 && (errno == EAGAIN || errno == EPIPE))) {
		close(fifofd);
		fifofd = -1;
	}
}

static void write_picked(const char *buf, size_t len);

static int handle_context_switch(enum action sel)
{
	int r = -1;

	switch (sel) {
	case SEL_CYCLE:
	case SEL_CYCLER:
		/* visit next and previous contexts */
		r = cfg.curctx;
		if (sel == SEL_CYCLE)
			do
				r = (r + 1) & ~CTX_MAX;
			while (!g_ctx[r].c_cfg.ctxactive);
		else {
			do /* Attempt to create a new context */
				r = (r + 1) & ~CTX_MAX;
			while (g_ctx[r].c_cfg.ctxactive && (r != (int)cfg.curctx));

			if (r == (int)cfg.curctx) /* If all contexts are active, reverse cycle */
				do
					r = (r + (CTX_MAX - 1)) & (CTX_MAX - 1);
				while (!g_ctx[r].c_cfg.ctxactive);
		}
		break;
	default: /* SEL_CTXN */
		r = sel - SEL_CTX1; /* Save the next context id */
		if ((int)cfg.curctx == r) {
			return -1;
		}
		break;
	}

	return r;
}
