		xstrsncpy(g_ctx[0].c_path, ipath, PATH_MAX_LEN);
		g_ctx[0].c_last[0] = g_ctx[0].c_name[0] = '\0';
		g_ctx[0].c_fltr[0] = (flt_type == FLT_REG) ? RFILTER : FILTER;
		g_ctx[0].c_fltr[1] = '\0';
		g_ctx[0].c_cfg = cfg;
	}

	newpath[0] = rundir[0] = runfile[0] = '\0';

	presel = cfg.filtermode ? SEL_FILTER : 0;

	pdents = xrealloc(pdents, total_dents * sizeof(struct entry));
	if (!pdents)
		errexit();

	/* Allocate buffer to hold names */
	pnamebuf = (char *)xrealloc(pnamebuf, NAMEBUF_INC);
	if (!pnamebuf) {
		free(pdents);
		errexit();
	}

	path = g_ctx[cfg.curctx].c_path;
	lastdir_ = g_ctx[cfg.curctx].c_last;
	lastname_ = g_ctx[cfg.curctx].c_name;

	if (g_state.initfile) {
		/* start file set: cursor on it */
	}

begin:
	if (chdir(path) == -1) {
		/* if the dir vanished, go up */
		printwarn(&presel);
		if (!xdiraccess(path)) {
			dir = xdirname(path);
			if (!strcmp(dir, path))
				goto nochange_begin;
			xstrsncpy(path, dir, PATH_MAX_LEN);
			goto begin;
		}
	}
nochange_begin:

	inotify_set(path);
	populate(path, lastname_);
	if (g_state.initfile) {
		g_state.initfile = 0;
	}

	while (1) {
		/* Place cursor on the last entry if ndents changed */
		redraw(path);

		if (g_state.fifomode == 0 && fifopath && ndents)
			notify_fifo(false, path);

nochange:
		sel = nextsel(presel);
		presel = 0;

		switch (sel) {
		case SEL_REDRAW:
			/* auto refresh or ^L */
			if (filterset() && !cfg.filtermode) {
				/* ^L clears active filter when set */
			}
			if (last_curscroll == -2) {
			}
			/* check if ^L with filter: toggled by presel? */
			if (g_state.move) {
				g_state.move = 0;
			}
			/* refresh dir */
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_BACK:
			if (!dir_changed) {
			}
			dir = xdirname(path);
			if (!strcmp(path, dir)) {
				/* at root */
				goto nochange;
			}
			if (!xdiraccess(dir)) {
				printwarn(&presel);
				goto nochange;
			}
			/* Save history */
			xstrsncpy(lastname_, xbasename(path), NAME_MAX_LEN + 1);
			xstrsncpy(lastdir_, path, PATH_MAX_LEN);
			xstrsncpy(path, dir, PATH_MAX_LEN);
			clearfilter();
			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_NAV_IN:
		case SEL_OPEN:
			if (!ndents)
				goto nochange;

			mkpath(path, pdents[cur].name, newpath);

			/* Cannot descend in empty directories */
			if (pdents[cur].flags & DIR_OR_DIRLNK) {
				if (!xdiraccess(newpath)) {
					printwarn(&presel);
					goto nochange;
				}
				xstrsncpy(lastdir_, path, PATH_MAX_LEN);
				xstrsncpy(path, newpath, PATH_MAX_LEN);
				lastname_[0] = '\0';
				clearfilter();
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}

			/* Picker mode: pick the file */
			if (g_state.picker && sel == SEL_OPEN) {
				if (selbufpos) {
					/* add? no: pick selection */
				}
				/* pick current file */
				selbufpos = 0;
				appendfpath(newpath, strlen(newpath) + 1);
				nselected = 1;
				g_state.picked = 1;
				return true;
			}

			if (sel == SEL_NAV_IN && cfg.nonavopen)
				goto nochange;

			if (!sb.st_size && S_ISREG(pdents[cur].mode)) {
				/* empty file */
			}
			if (S_ISREG(pdents[cur].mode) && !pdents[cur].size) {
				printwait("empty! edit/open with", &presel);
				goto nochange;
			}

			if (S_ISREG(pdents[cur].mode) || S_ISLNK(pdents[cur].mode)) {
				if (cfg.useeditor && is_textfile(newpath)) {
					spawn(get_editor(), newpath, NULL, NULL, F_CLI);
					if (!cfg.waitedit) {
					}
				} else if (cfg.cliopener) {
					spawn(get_opener(), newpath, NULL, NULL, F_CLI);
				} else {
					spawn(get_opener(), newpath, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
				}
				if (g_state.autonext && cur != ndents - 1)
					move_cursor((cur + 1) % ndents, 0);
				continue;
			}
			/* other types: do nothing */
			goto nochange;
		case SEL_NEXT:
			if (ndents) {
				if (cur != ndents - 1)
					move_cursor(cur + 1, 0);
				else if (cfg.rollover)
					move_cursor(0, 0);
			}
			break;
		case SEL_PREV:
			if (ndents) {
				if (cur)
					move_cursor(cur - 1, 0);
				else if (cfg.rollover)
					move_cursor(ndents - 1, 0);
			}
			break;
		case SEL_PGDN:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll += onscreen - 1;
					move_cursor(oldscroll + onscreen - 1, 1);
				} else
					move_cursor(ndents - 1, 1);
			}
			break;
		case SEL_CTRL_D:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll += onscreen >> 1;
					move_cursor(oldscroll + onscreen - 1, 1);
				} else
					move_cursor(ndents - 1, 1);
			}
			break;
		case SEL_PGUP:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll -= onscreen - 1;
					move_cursor(oldscroll, 1);
				} else
					move_cursor(0, 1);
			}
			break;
		case SEL_CTRL_U:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll -= onscreen >> 1;
					move_cursor(oldscroll, 1);
				} else
					move_cursor(0, 1);
			}
			break;
		case SEL_HOME:
			move_cursor(0, 1);
			break;
		case SEL_END:
			move_cursor(ndents - 1, 1);
			break;
		case SEL_FIRST:
			/* first file (non-dir) */
			if (ndents) {
				for (r = 0; r < ndents; ++r)
					if (!(pdents[r].flags & DIR_OR_DIRLNK))
						break;
				if (r < ndents)
					move_cursor(r, 0);
			}
			break;
		case SEL_JUMP:
			if (ndents) {
				tmp = xreadline(NULL, "jump (+n/-n/n): ");
				if (!tmp || !*tmp)
					break;
				{
					char *end;
					long n = strtol(tmp, &end, 10);
					if (end == tmp)
						break;
					if (*tmp == '+' || *tmp == '-') {
						move_cursor(cur + (int)n, 0);
					} else if (n >= 1 && n <= ndents)
						move_cursor((int)n - 1, 0);
				}
			}
			break;
		case SEL_YOUNG:
			if (ndents) {
				for (r = (cur + 1) % ndents; r != cur; r = (r + 1) % ndents)
					if (pdents[r].flags & FILE_YOUNG)
						break;
				if (pdents[r].flags & FILE_YOUNG)
					move_cursor(r, 0);
			}
			break;
		case SEL_CDHOME:
		case SEL_CDBEGIN:
		case SEL_CDLAST:
		case SEL_CDROOT:
			switch (sel) {
			case SEL_CDHOME:
				dir = homedir;
				break;
			case SEL_CDBEGIN:
				dir = initpath;
				break;
			case SEL_CDLAST:
				dir = lastdir_;
				break;
			default: /* SEL_CDROOT */
				dir = "/";
				break;
			}

			if (!dir || !*dir) {
				printwait("not set", &presel);
				goto nochange;
			}

			if (!xdiraccess(dir)) {
				printwarn(&presel);
				goto nochange;
			}

			if (strcmp(path, dir) == 0) {
				goto nochange;
			}

			/* SEL_CDLAST: dir pointing to lastdir */
			xstrsncpy(newpath, dir, PATH_MAX_LEN);
			lastname_[0] = '\0';
			xstrsncpy(lastdir_, path, PATH_MAX_LEN);
			xstrsncpy(path, newpath, PATH_MAX_LEN);
			clearfilter();
			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_BMOPEN:
			/* select bookmark */
			if (bms_env && *bms_env) {
				/* prompt for key */
				char prompt[64];
				int key;
				snprintf(prompt, sizeof(prompt), "key: ");
				key = get_input(prompt);
				if (key == 27 || key == '\r' || key == '\n' || key == ERR)
					break;
				if (!get_bm_loc(key, newpath)) {
					printwait("invalid key", &presel);
					goto nochange;
				}
				if (!xdiraccess(newpath)) {
					printwarn(&presel);
					goto nochange;
				}
				if (strcmp(path, newpath) == 0)
					break;
				lastname_[0] = '\0';
				xstrsncpy(lastdir_, path, PATH_MAX_LEN);
				xstrsncpy(path, newpath, PATH_MAX_LEN);
				clearfilter();
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
			/* go to bookmarks dir and filter */
			snprintf(newpath, PATH_MAX_LEN, "%s/bookmarks", cfgpath);
			if (!xdiraccess(newpath)) {
				printwarn(&presel);
				goto nochange;
			}
			if (strcmp(path, newpath)) {
				lastname_[0] = '\0';
				xstrsncpy(lastdir_, path, PATH_MAX_LEN);
				xstrsncpy(path, newpath, PATH_MAX_LEN);
				clearfilter();
			}
			g_state.selbm = 1;
			presel = SEL_FILTER;
			goto begin;
		case SEL_REMOTE:
			printwait("not supported", &presel);
			goto nochange;
		case SEL_CYCLE:
		case SEL_CYCLER:
		case SEL_CTX1:
		case SEL_CTX2:
		case SEL_CTX3:
		case SEL_CTX4:
		case SEL_CTX5:
		case SEL_CTX6:
		case SEL_CTX7:
		case SEL_CTX8:
			r = handle_context_switch(sel);
			if (r < 0)
				continue;
			savecurctx(path, ndents ? pdents[cur].name : NULL, r);

			/* Reset the pointers */
			path = g_ctx[r].c_path;
			lastdir_ = g_ctx[r].c_last;
			lastname_ = g_ctx[r].c_name;

			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_MARK:
			free(mark);
			mark = strdup(path);
			printwait(mark, &presel);
			goto nochange;
		case SEL_BMARK:
			/* create bookmark: symlink in bookmarks dir */
			{
				char *name;
				snprintf(newpath, PATH_MAX_LEN, "%s/bookmarks", cfgpath);
				tmp = xreadline(xbasename(path), "name: ");
				if (!tmp || !*tmp)
					break;
				name = tmp;
				{
					char target[PATH_MAX_LEN];
					mkpath(newpath, name, target);
					if (symlink(path, target) == -1)
						printwarn(&presel);
					else
						printwait(target, &presel);
				}
			}
			goto nochange;
		case SEL_FLTR:
			/* Unset filter on 'Esc' */
			presel = SEL_FILTER;
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto nochange;
		case SEL_MFLTR:
			cfg.filtermode ^= 1;
			if (cfg.filtermode) {
				presel = SEL_FILTER;
				goto nochange;
			}
			/* Save current */
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			clearfilter();
			goto begin;
		case SEL_HIDDEN:
			cfg.showhidden ^= 1;
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_DETAIL:
			cfg.showdetail ^= 1;
			cfg.blkorder = 0;
			cfg.apparentsz = 0;
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_STATS:
			if (!ndents)
				break;
			for (;;) {
				r = show_stats_popup(path);
				if (r == 'j') {
					if (cur != ndents - 1)
						move_cursor(cur + 1, 0);
					else if (cfg.rollover)
						move_cursor(0, 0);
					redraw(path);
					refresh();
					continue;
				} else if (r == 'k') {
					if (cur)
						move_cursor(cur - 1, 0);
					else if (cfg.rollover)
						move_cursor(ndents - 1, 0);
					redraw(path);
					refresh();
					continue;
				}
				break;
			}
			break;
		case SEL_CHMODX:
			if (!ndents)
				break;
			mkpath(path, pdents[cur].name, newpath);
			if (lstat(newpath, &sb) == -1) {
				printwarn(&presel);
				goto nochange;
			}
			if (!S_ISREG(sb.st_mode)) {
				printwait("not regular file", &presel);
				goto nochange;
			}
			if (chmod(newpath, (sb.st_mode & 0100) ? (sb.st_mode & ~0111) : (sb.st_mode | 0111)) == -1) {
				printwarn(&presel);
				goto nochange;
			}
			xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_ARCHIVE:
			if (!ndents && !selbufpos)
				break;
			r = get_cur_or_sel();
			if (!r) {
				goto nochange;
			}
			if (r == 's') {
				tmp = xreadline(NULL, "archive [path/]name: ");
			} else
				tmp = xreadline(pdents[cur].name, "archive [path/]name: ");
			if (!tmp || !*tmp)
				break;
			{
				char cmd[32];
				char archive[PATH_MAX_LEN];
				mkpath(path, tmp, archive);
				get_archive_cmd(cmd, tmp);
				if (r == 's') {
					archive_selection(cmd, archive, path);
					clearselection();
				} else {
					char *argv[8];
					int n = 0;
					char cmdbuf[32];
					char *p, *saveptr;
					xstrsncpy(cmdbuf, cmd, sizeof(cmdbuf));
					for (p = strtok_r(cmdbuf, " ", &saveptr); p; p = strtok_r(NULL, " ", &saveptr))
						argv[n++] = p;
					argv[n++] = archive;
					argv[n++] = pdents[cur].name;
					argv[n] = NULL;
					exitcurses();
					{
						pid_t pid = xfork(F_NORMAL);
						if (pid == 0) {
							execvp(argv[0], argv);
							_exit(EXIT_FAILURE);
						}
						join(pid, F_NORMAL);
					}
					refresh();
				}
				xstrsncpy(lastname_, xbasename(archive), NAME_MAX_LEN + 1);
			}
			goto begin;
		case SEL_SORT:
			r = get_input("'a'u/'d'u/'e'xt/'r'ev/'s'z/'t'm/'v'er/'c'lr/'^T'?");
			if (r == 'a' || r == 'd' || r == 'e' || r == 'r' || r == 's' || r == 't' || r == 'v' || r == 'c' || r == CONTROL('T')) {
				set_sort_flags(r);
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
			break;
		case SEL_SEL:
			if (!ndents)
				goto nochange;

			startselection();
			/* Toggle selection status */
			mkpath(path, pdents[cur].name, newpath);
			if (pdents[cur].flags & FILE_SELECTED) {
				pdents[cur].flags &= ~FILE_SELECTED;
				rmfromselbuf(newpath, 0);
			} else {
				pdents[cur].flags |= FILE_SELECTED;
				addtoselbuf(newpath);
			}

			if (g_state.rangesel) {
				g_state.rangesel = 0;
			}

			/* move cursor to next entry if this is not the last entry */
			if (!g_state.stayonsel && (cur != ndents - 1))
				move_cursor((cur + 1) % ndents, 0);
			break;
		case SEL_SELMUL:
			if (!ndents)
				goto nochange;

			startselection();
			g_state.rangesel ^= 1;

			if (g_state.rangesel) { /* Range selection started */
				selstartid = cur;
				continue;
			}

			/* Range selection ended */
			selendid = cur;
			if (selstartid > selendid) {
				r = selstartid;
				selstartid = selendid;
				selendid = r;
			}
			for (r = selstartid; r <= selendid; ++r) {
				if (!(pdents[r].flags & FILE_SELECTED)) {
					mkpath(path, pdents[r].name, newpath);
					pdents[r].flags |= FILE_SELECTED;
					appendfpath(newpath, strlen(newpath) + 1);
					++nselected;
				}
			}
			writeselbuf();
			continue;
		case SEL_SELALL:
		case SEL_SELINV:
			if (!ndents)
				goto nochange;

			startselection();
			if (g_state.rangesel)
				g_state.rangesel = 0;

			if (sel == SEL_SELALL) {
				for (r = 0; r < ndents; ++r) {
					if (!(pdents[r].flags & FILE_SELECTED)) {
						mkpath(path, pdents[r].name, newpath);
						pdents[r].flags |= FILE_SELECTED;
						appendfpath(newpath, strlen(newpath) + 1);
						++nselected;
					}
				}
				writeselbuf();
			} else
				invertselbuf(path);
			continue;
		case SEL_SELEDIT:
			if (!selbufpos) {
				printwait("0 selected", &presel);
				goto nochange;
			}
			{
				int fd = create_tmp_file();
				if (fd == -1)
					break;
				{
					size_t pos = 0;
					while (pos < selbufpos) {
						dprintf(fd, "%s\n", pselbuf + pos);
						pos += strlen(pselbuf + pos) + 1;
					}
				}
				close(fd);
				run_editor(g_tmpfpath);
				selbuf_from_file(g_tmpfpath, false);
				unlink(g_tmpfpath);
				writeselbuf();
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_CP:
		case SEL_MV:
			if (!cpmv_selection(sel == SEL_MV, path)) {
				presel = MSGWAIT;
				goto nochange;
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_CPMVAS:
			if (!selbufpos) {
				printwait("0 selected", &presel);
				goto nochange;
			}
			r = get_input("'c'p/'m'v as?");
			if (r != 'c' && r != 'm')
				break;
			cpmv_as(r == 'm', path);
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_RM:
		case SEL_RMX:
			if (!ndents && !selbufpos)
				break;
			{
				bool use_trash = (sel == SEL_RM) && g_state.trash;
				if (selbufpos && ndents) {
					r = get_input("'c'urrent/'s'el?");
					if (r != 'c' && r != 's')
						break;
				} else if (selbufpos)
					r = 's';
				else
					r = 'c';

				if (r == 's') {
					if (!rmmulstr(NULL, use_trash))
						break;
					clearselection();
				} else {
					mkpath(path, pdents[cur].name, newpath);
					if (!xrm(newpath, use_trash))
						break;
					/* cursor stays at same index */
					if (cur < ndents - 1)
						xstrsncpy(lastname_, pdents[cur + 1].name, NAME_MAX_LEN + 1);
					else if (cur > 0)
						xstrsncpy(lastname_, pdents[cur - 1].name, NAME_MAX_LEN + 1);
					else
						lastname_[0] = '\0';
					goto begin;
				}
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_OPENWITH:
			if (!ndents)
				break;
			mkpath(path, pdents[cur].name, newpath);
			if (g_state.xprompt)
				tmp = xreadline(NULL, "open with: ");
			else
				tmp = getreadline("open with: ");
			if (!tmp || !*tmp)
				break;
			{
				char cmd[CMD_LEN_MAX];
				xstrsncpy(cmd, tmp, sizeof(cmd));
				if (!g_state.xprompt)
					free(tmp);
				r = get_input("['g'ui]/'c'li?");
				if (r == 'c')
					spawn(cmd, newpath, NULL, NULL, F_CLI);
				else if (r == 'g' || r == '\r' || r == '\n')
					spawn(cmd, newpath, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
				else
					break;
			}
			break;
		case SEL_NEW:
			r = get_input("['f'ile]/'d'ir/'s'ym/'h'ard?");
			if (r == '\r' || r == '\n')
				r = 'f';
			if (r != 'f' && r != 'd' && r != 's' && r != 'h')
				break;

			if (r == 'f' || r == 'd') {
				tmp = xreadline(NULL, "[path/]name: ");
				if (!tmp || !*tmp)
					break;
				mkpath(path, tmp, newpath);
				{
					/* create parents */
					char parent[PATH_MAX_LEN];
					xstrsncpy(parent, newpath, PATH_MAX_LEN);
					char *slash = strrchr(parent, '/');
					if (slash && slash != parent) {
						*slash = '\0';
						/* mkdir -p */
						char *p = parent + 1;
						while ((p = strchr(p, '/'))) {
							*p = '\0';
							mkdir(parent, 0755);
							*p = '/';
							++p;
						}
						mkdir(parent, 0755);
					}
				}
				if (access(newpath, F_OK) == 0) {
					printwait("entry exists", &presel);
					goto nochange;
				}
				if (r == 'f') {
					int fd = open(newpath, O_CREAT | O_WRONLY, 0600);
					if (fd == -1) {
						printwarn(&presel);
						goto nochange;
					}
					close(fd);
				} else {
					if (mkdir(newpath, 0755) == -1) {
						printwarn(&presel);
						goto nochange;
					}
				}
				/* cursor on the first component created */
				{
					char *first = tmp;
					while (*first == '/')
						++first;
					char *sl = strchr(first, '/');
					if (sl)
						*sl = '\0';
					xstrsncpy(lastname_, first, NAME_MAX_LEN + 1);
				}
				goto begin;
			}

			/* link(s) */
			{
				int c = get_cur_or_sel();
				if (!c)
					break;
				if (c == 'c') {
					tmp = xreadline(pdents[cur].name, "link suffix [@ for none]: ");
				} else
					tmp = xreadline(NULL, "link suffix [@ for none]: ");
				if (!tmp || !*tmp)
					break;
				/* for current: tmp is the new link name */
				if (c == 'c') {
					char target[PATH_MAX_LEN];
					mkpath(path, pdents[cur].name, target);
					mkpath(path, tmp, newpath);
					int ret = (r == 's') ? symlink(target, newpath) : link(target, newpath);
					if (ret == -1) {
						printwarn(&presel);
						goto nochange;
					}
					xstrsncpy(lastname_, tmp, NAME_MAX_LEN + 1);
				} else {
					size_t pos = 0;
					int cnt = 0;
					char suffix[NAME_MAX_LEN + 1];
					xstrsncpy(suffix, tmp, sizeof(suffix));
					if (!strcmp(suffix, "@"))
						suffix[0] = '\0';
					while (pos < selbufpos) {
						char *src = pselbuf + pos;
						snprintf(newpath, PATH_MAX_LEN, "%s/%s%s", path, xbasename(src), suffix);
						if (((r == 's') ? symlink(src, newpath) : link(src, newpath)) == 0)
							++cnt;
						pos += strlen(src) + 1;
					}
					{
						char msg[64];
						snprintf(msg, sizeof(msg), "%d link%s created", cnt, cnt == 1 ? "" : "s");
						printwait(msg, &presel);
					}
					clearselection();
					if (ndents)
						xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				}
				goto begin;
			}
		case SEL_RENAME:
			if (!ndents)
				break;
			tmp = xreadline(pdents[cur].name, "");
			if (!tmp || !*tmp)
				break;
			if (!strcmp(tmp, pdents[cur].name))
				break;
			mkpath(path, tmp, newpath);
			{
				char oldpath[PATH_MAX_LEN];
				mkpath(path, pdents[cur].name, oldpath);
				if (access(newpath, F_OK) == 0) {
					r = get_input("overwrite?");
					if (!xconfirm(r))
						break;
				}
				if (rename(oldpath, newpath) == -1) {
					printwarn(&presel);
					goto nochange;
				}
				xstrsncpy(lastname_, xbasename(newpath), NAME_MAX_LEN + 1);
			}
			goto begin;
		case SEL_RENAMEMUL:
			{
				/* batch rename via editor */
				int fd = create_tmp_file();
				if (fd == -1)
					break;
				{
					char **names = NULL;
					int n = 0;
					if (selbufpos) {
						size_t pos = 0;
						while (pos < selbufpos) {
							dprintf(fd, "%s\n", pselbuf + pos);
							names = xrealloc(names, (n + 1) * sizeof(char *));
							names[n++] = strdup(pselbuf + pos);
							pos += strlen(pselbuf + pos) + 1;
						}
					} else {
						for (r = 0; r < ndents; ++r) {
							dprintf(fd, "%s\n", pdents[r].name);
							names = xrealloc(names, (n + 1) * sizeof(char *));
							names[n++] = strdup(pdents[r].name);
						}
					}
					close(fd);
					run_editor(g_tmpfpath);
					{
						FILE *fp = fopen(g_tmpfpath, "r");
						char line[PATH_MAX_LEN];
						int i = 0, renamed = 0;
						if (fp) {
							while (fgets(line, sizeof(line), fp)) {
								size_t l = strlen(line);
								while (l && (line[l - 1] == '\n' || line[l - 1] == '\r'))
									line[--l] = '\0';
								if (i >= n)
									break;
								if (*line && strcmp(line, names[i])) {
									char src[PATH_MAX_LEN], dst[PATH_MAX_LEN];
									mkpath(path, names[i], src);
									mkpath(path, line, dst);
									exitcurses();
									{
										char *argv[6] = {"mv", "-i", "--", src, dst, NULL};
										pid_t pid = xfork(F_NORMAL);
										if (pid == 0) {
											execvp(argv[0], argv);
											_exit(EXIT_FAILURE);
										}
										join(pid, F_NORMAL);
									}
									refresh();
									++renamed;
								} else if (!*line) {
									/* empty line: remove */
								}
								++i;
							}
							fclose(fp);
						}
						(void)renamed;
					}
					for (int k = 0; k < n; ++k)
						free(names[k]);
					free(names);
					unlink(g_tmpfpath);
				}
				if (selbufpos)
					clearselection();
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			}
			goto begin;
		case SEL_UMOUNT:
			printwait("not supported", &presel);
			goto nochange;
		case SEL_HELP:
			show_help(path);
			if (cfg.filtermode)
				presel = SEL_FILTER;
			continue;
		case SEL_AUTONEXT:
			g_state.autonext ^= 1;
			printwait(g_state.autonext ? "auto-advance on" : "auto-advance off", &presel);
			goto nochange;
		case SEL_EDIT:
			if (!ndents)
				break;
			mkpath(path, pdents[cur].name, newpath);
			spawn(get_editor(), newpath, NULL, NULL, F_CLI);
			continue;
		case SEL_PLUGIN:
		case SEL_PLUGKEY:
			printwait("plugin not found", &presel);
			goto nochange;
		case SEL_SELSIZE:
			{
				/* total size of listed selected entries */
				off_t total = 0;
				int n = 0;
				for (r = 0; r < ndents; ++r)
					if (pdents[r].flags & FILE_SELECTED) {
						total += cfg.blkorder ? (off_t)pdents[r].blocks << 9 : pdents[r].size;
						++n;
					}
				if (!n) {
					printwait("0 selected", &presel);
					goto nochange;
				}
				{
					char msg[64];
					snprintf(msg, sizeof(msg), "%d selected: %s", n, coolsize(total));
					printwait(msg, &presel);
				}
			}
			goto nochange;
		case SEL_SHELL:
			run_shell(path);
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_LAUNCH:
			tmp = g_state.xprompt ? xreadline(NULL, "launch: ") : getreadline("launch: ");
			if (!tmp || !*tmp)
				break;
			{
				char cmd[CMD_LEN_MAX];
				xstrsncpy(cmd, tmp, sizeof(cmd));
				if (!g_state.xprompt)
					free(tmp);
				spawn(cmd, NULL, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
			}
			break;
		case SEL_PROMPT:
			{
				char *shell = get_shell();
				if (ndents) {
					setenv("NNN_CUR", pdents[cur].name, 1);
				}
				tmp = g_state.xprompt ? xreadline(NULL, "> ") : getreadline("> ");
				if (!tmp || !*tmp)
					break;
				{
					char cmd[CMD_LEN_MAX];
					xstrsncpy(cmd, tmp, sizeof(cmd));
					if (!g_state.xprompt)
						free(tmp);
					spawn(shell, "-c", cmd, NULL, F_CLI | F_CONFIRM);
				}
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_LOCK:
			{
				char *locker = lockcmd_env;
				if (locker && *locker)
					spawn(locker, NULL, NULL, NULL, F_CLI);
				else if (is_executable_in_path("vlock"))
					spawn("vlock", NULL, NULL, NULL, F_CLI);
				else if (is_executable_in_path("bashlock"))
					spawn("bashlock", NULL, NULL, NULL, F_CLI);
				else {
					printwait("missing locker", &presel);
					goto nochange;
				}
			}
			break;
		case SEL_SESSIONS:
			r = get_input("'s'ave/'l'oad/'r'estore?");
			if (r != 's' && r != 'l' && r != 'r')
				break;
			printwait("not supported", &presel);
			goto nochange;
		case SEL_EXPORT:
			{
				int fd = create_tmp_file();
				if (fd == -1)
					break;
				for (r = 0; r < ndents; ++r)
					dprintf(fd, "%s\n", pdents[r].name);
				close(fd);
				run_editor(g_tmpfpath);
				unlink(g_tmpfpath);
			}
			break;
		case SEL_TIMETYPE:
			r = get_input("'a'ccess / 'c'hange / 'm'od [m]");
			if (r == 'a' || r == 'c' || r == 'm' || r == '\r' || r == '\n') {
				if (r == 'a')
					cfg.timetype = T_ACCESS;
				else if (r == 'c')
					cfg.timetype = T_CHANGE;
				else
					cfg.timetype = T_MOD;
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
			break;
		case SEL_QUITCTX:
			{
				int ctx = cfg.curctx;
				/* Find the next active context */
				g_ctx[ctx].c_cfg.ctxactive = 0;
				for (r = (ctx + 1) & (CTX_MAX - 1); r != ctx; r = (r + 1) & (CTX_MAX - 1))
					if (g_ctx[r].c_cfg.ctxactive)
						break;
				if (r == ctx) {
					/* last context: quit */
					if (g_state.picker && selbufpos) {
						g_state.picked = 1;
					}
					return true;
				}
				/* switch to context r */
				{
					settings tmpcfg = g_ctx[r].c_cfg;
					tmpcfg.curctx = r;
					cfg = tmpcfg;
					path = g_ctx[r].c_path;
					lastdir_ = g_ctx[r].c_last;
					lastname_ = g_ctx[r].c_name;
				}
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
		case SEL_QUITCD:
			g_state.forcequit = 1;
			write_lastdir(path, NULL);
			return true;
		case SEL_QUIT:
			if (count_active_ctx() > 1 && g_state.quitconfirm) {
				r = get_input("Quit all contexts?");
				if (!xconfirm(r))
					break;
			}
			return true;
		case SEL_QUITERR:
			if (g_state.picker)
				g_state.picked = 1;
			g_state.forcequit = 1;
			return true;
		case SEL_FIFO:
			if (fifopath && ndents)
				notify_fifo(true, path);
			goto nochange;
		case SEL_UNFLTRQUIT:
			/* Alt+Esc: unfilter and quit context */
			if (filterset()) {
				clearfilter();
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				goto begin;
			}
			sel = SEL_QUITCTX;
			{
				int ctx = cfg.curctx;
				g_ctx[ctx].c_cfg.ctxactive = 0;
				for (r = (ctx + 1) & (CTX_MAX - 1); r != ctx; r = (r + 1) & (CTX_MAX - 1))
					if (g_ctx[r].c_cfg.ctxactive)
						break;
				if (r == ctx)
					return true;
				{
					settings tmpcfg = g_ctx[r].c_cfg;
					tmpcfg.curctx = r;
					cfg = tmpcfg;
					path = g_ctx[r].c_path;
					lastdir_ = g_ctx[r].c_last;
					lastname_ = g_ctx[r].c_name;
				}
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
		case SEL_FILTER:
			/* filter prompt */
			r = filterentries(path, lastname_);
			if (r == KEY_F(63)) { /* Alt+Esc */
				presel = 0;
				sel = SEL_UNFLTRQUIT;
				if (filterset()) {
					clearfilter();
					goto begin;
				}
				/* quit context */
				{
					int ctx = cfg.curctx;
					g_ctx[ctx].c_cfg.ctxactive = 0;
					for (r = (ctx + 1) & (CTX_MAX - 1); r != ctx; r = (r + 1) & (CTX_MAX - 1))
						if (g_ctx[r].c_cfg.ctxactive)
							break;
					if (r == ctx)
						return true;
					{
						settings tmpcfg = g_ctx[r].c_cfg;
						tmpcfg.curctx = r;
						cfg = tmpcfg;
						path = g_ctx[r].c_path;
						lastdir_ = g_ctx[r].c_last;
						lastname_ = g_ctx[r].c_name;
					}
					if (cfg.filtermode)
						presel = SEL_FILTER;
					goto begin;
				}
			}
			if (r == KEY_F(62)) { /* Alt+key */
				presel = 0;
				goto nochange;
			}
			if (r == 27) {
				/* Esc: exit prompt */
				if (g_state.selbm) {
					g_state.selbm = 0;
				}
				presel = 0;
				break;
			}
			if (r == KEY_ENTER || r == '\r' || r == '\n') {
				presel = SEL_OPEN;
				/* process via the open path with key translation */
				{
					/* emulate SEL_OPEN */
					sel = SEL_OPEN;
				}
				/* fallthrough into switch again by looping */
				{
					int saved = presel;
					presel = 0;
					/* handle open inline */
					if (!ndents)
						goto nochange;
					mkpath(path, pdents[cur].name, newpath);
					if (pdents[cur].flags & DIR_OR_DIRLNK) {
						if (!xdiraccess(newpath)) {
							printwarn(&presel);
							goto nochange;
						}
						xstrsncpy(lastdir_, path, PATH_MAX_LEN);
						xstrsncpy(path, newpath, PATH_MAX_LEN);
						lastname_[0] = '\0';
						clearfilter();
						if (cfg.filtermode)
							presel = SEL_FILTER;
						goto begin;
					}
					(void)saved;
					if (g_state.picker) {
						selbufpos = 0;
						appendfpath(newpath, strlen(newpath) + 1);
						nselected = 1;
						g_state.picked = 1;
						return true;
					}
					if (S_ISREG(pdents[cur].mode) && !pdents[cur].size) {
						printwait("empty! edit/open with", &presel);
						goto nochange;
					}
					if (cfg.useeditor && is_textfile(newpath))
						spawn(get_editor(), newpath, NULL, NULL, F_CLI);
					else if (cfg.cliopener)
						spawn(get_opener(), newpath, NULL, NULL, F_CLI);
					else
						spawn(get_opener(), newpath, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
					if (cfg.filtermode)
						presel = SEL_FILTER;
					continue;
				}
			}
			/* other keys: process in main loop */
			{
				/* translate key r to action */
				uint_t i;
				int act = 0;
				if (r == KEY_RESIZE) {
					goto begin;
				}
				for (i = 0; bindings[i].sym; ++i)
					if (r == bindings[i].sym) {
						act = bindings[i].act;
						break;
					}
				if (!act)
					goto nochange;
				presel = act;
				goto nochange;
			}
		default:
			if (xlines != LINES || xcols != COLS) {
				goto begin;
			}
			goto nochange;
		} /* switch (sel) */
	}
	(void)rangesel; (void)rundir; (void)runfile; (void)watch; (void)dir_changed;
	return false;
}
EOF
echo ok"}

actions.command:
cat >> /workspace/src/nnn.c <<'EOF'

static void write_picked(const char *buf, size_t len)
{
	(void)buf; (void)len;
}

static void save_selection_for_pick(void)
{
	g_state.picked = 1;
}

static bool remove_dir_if_empty_unused(void) { return false; }

static void setdirwatch(void)
{
	/* nothing extra */
}

/* Run shell */
static void run_shell(char *path)
{
	setenv("NNN_LVL", "1", 1); /* nesting level */
	{
		char *lvl = getenv("NNN_LVL");
		(void)lvl;
	}
	chdir(path);
	spawn(get_shell(), NULL, NULL, NULL, F_CLI);
}

static bool browse(char *ipath, const char *session, int pkey)
{
	char newpath[PATH_MAX_LEN];
	char rundir[PATH_MAX_LEN];
	char runfile[NAME_MAX_LEN + 1];
	char *path, *lastdir_, *lastname_, *dir, *tmp;
	int r = -1, presel, selstartid = 0, selendid = 0;
	enum action sel;
	bool dir_changed = false, rangesel = false;
	struct stat sb;
	bool watch = false;

	(void)session; (void)pkey;

	/* setup first context */
	if (!session) {
		g_ctx[0].c_cfg.ctxactive = 1;
		xstrsncpy(g_ctx[0].c_path, ipath, PATH_MAX_LEN);
		g_ctx[0].c_last[0] = g_ctx[0].c_name[0] = '\0';
		g_ctx[0].c_fltr[0] = (flt_type == FLT_REG) ? RFILTER : FILTER;
		g_ctx[0].c_fltr[1] = '\0';
		g_ctx[0].c_cfg = cfg;
	}

	newpath[0] = rundir[0] = runfile[0] = '\0';

	presel = cfg.filtermode ? SEL_FILTER : 0;

	pdents = xrealloc(pdents, total_dents * sizeof(struct entry));
	if (!pdents)
		errexit();

	/* Allocate buffer to hold names */
	pnamebuf = (char *)xrealloc(pnamebuf, NAMEBUF_INC);
	if (!pnamebuf) {
		free(pdents);
		errexit();
	}

	path = g_ctx[cfg.curctx].c_path;
	lastdir_ = g_ctx[cfg.curctx].c_last;
	lastname_ = g_ctx[cfg.curctx].c_name;

	if (g_state.initfile) {
		/* start file set: cursor on it */
	}

begin:
	if (chdir(path) == -1) {
		/* if the dir vanished, go up */
		printwarn(&presel);
		if (!xdiraccess(path)) {
			dir = xdirname(path);
			if (!strcmp(dir, path))
				goto nochange_begin;
			xstrsncpy(path, dir, PATH_MAX_LEN);
			goto begin;
		}
	}
nochange_begin:

	inotify_set(path);
	populate(path, lastname_);
	if (g_state.initfile) {
		g_state.initfile = 0;
	}

	while (1) {
		/* Place cursor on the last entry if ndents changed */
		redraw(path);

		if (g_state.fifomode == 0 && fifopath && ndents)
			notify_fifo(false, path);

nochange:
		sel = nextsel(presel);
		presel = 0;

		switch (sel) {
		case SEL_REDRAW:
			/* auto refresh or ^L */
			if (filterset() && !cfg.filtermode) {
				/* ^L clears active filter when set */
			}
			if (last_curscroll == -2) {
			}
			/* check if ^L with filter: toggled by presel? */
			if (g_state.move) {
				g_state.move = 0;
			}
			/* refresh dir */
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_BACK:
			if (!dir_changed) {
			}
			dir = xdirname(path);
			if (!strcmp(path, dir)) {
				/* at root */
				goto nochange;
			}
			if (!xdiraccess(dir)) {
				printwarn(&presel);
				goto nochange;
			}
			/* Save history */
			xstrsncpy(lastname_, xbasename(path), NAME_MAX_LEN + 1);
			xstrsncpy(lastdir_, path, PATH_MAX_LEN);
			xstrsncpy(path, dir, PATH_MAX_LEN);
			clearfilter();
			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_NAV_IN:
		case SEL_OPEN:
			if (!ndents)
				goto nochange;

			mkpath(path, pdents[cur].name, newpath);

			/* Cannot descend in empty directories */
			if (pdents[cur].flags & DIR_OR_DIRLNK) {
				if (!xdiraccess(newpath)) {
					printwarn(&presel);
					goto nochange;
				}
				xstrsncpy(lastdir_, path, PATH_MAX_LEN);
				xstrsncpy(path, newpath, PATH_MAX_LEN);
				lastname_[0] = '\0';
				clearfilter();
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}

			/* Picker mode: pick the file */
			if (g_state.picker && sel == SEL_OPEN) {
				if (selbufpos) {
					/* add? no: pick selection */
				}
				/* pick current file */
				selbufpos = 0;
				appendfpath(newpath, strlen(newpath) + 1);
				nselected = 1;
				g_state.picked = 1;
				return true;
			}

			if (sel == SEL_NAV_IN && cfg.nonavopen)
				goto nochange;

			if (!sb.st_size && S_ISREG(pdents[cur].mode)) {
				/* empty file */
			}
			if (S_ISREG(pdents[cur].mode) && !pdents[cur].size) {
				printwait("empty! edit/open with", &presel);
				goto nochange;
			}

			if (S_ISREG(pdents[cur].mode) || S_ISLNK(pdents[cur].mode)) {
				if (cfg.useeditor && is_textfile(newpath)) {
					spawn(get_editor(), newpath, NULL, NULL, F_CLI);
					if (!cfg.waitedit) {
					}
				} else if (cfg.cliopener) {
					spawn(get_opener(), newpath, NULL, NULL, F_CLI);
				} else {
					spawn(get_opener(), newpath, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
				}
				if (g_state.autonext && cur != ndents - 1)
					move_cursor((cur + 1) % ndents, 0);
				continue;
			}
			/* other types: do nothing */
			goto nochange;
		case SEL_NEXT:
			if (ndents) {
				if (cur != ndents - 1)
					move_cursor(cur + 1, 0);
				else if (cfg.rollover)
					move_cursor(0, 0);
			}
			break;
		case SEL_PREV:
			if (ndents) {
				if (cur)
					move_cursor(cur - 1, 0);
				else if (cfg.rollover)
					move_cursor(ndents - 1, 0);
			}
			break;
		case SEL_PGDN:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll += onscreen - 1;
					move_cursor(oldscroll + onscreen - 1, 1);
				} else
					move_cursor(ndents - 1, 1);
			}
			break;
		case SEL_CTRL_D:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll += onscreen >> 1;
					move_cursor(oldscroll + onscreen - 1, 1);
				} else
					move_cursor(ndents - 1, 1);
			}
			break;
		case SEL_PGUP:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll -= onscreen - 1;
					move_cursor(oldscroll, 1);
				} else
					move_cursor(0, 1);
			}
			break;
		case SEL_CTRL_U:
			if (ndents) {
				int onscreen = xlines - 4;
				if (ndents > onscreen) {
					int oldscroll = curscroll;
					curscroll -= onscreen >> 1;
					move_cursor(oldscroll, 1);
				} else
					move_cursor(0, 1);
			}
			break;
		case SEL_HOME:
			move_cursor(0, 1);
			break;
		case SEL_END:
			move_cursor(ndents - 1, 1);
			break;
		case SEL_FIRST:
			/* first file (non-dir) */
			if (ndents) {
				for (r = 0; r < ndents; ++r)
					if (!(pdents[r].flags & DIR_OR_DIRLNK))
						break;
				if (r < ndents)
					move_cursor(r, 0);
			}
			break;
		case SEL_JUMP:
			if (ndents) {
				tmp = xreadline(NULL, "jump (+n/-n/n): ");
				if (!tmp || !*tmp)
					break;
				{
					char *end;
					long n = strtol(tmp, &end, 10);
					if (end == tmp)
						break;
					if (*tmp == '+' || *tmp == '-') {
						move_cursor(cur + (int)n, 0);
					} else if (n >= 1 && n <= ndents)
						move_cursor((int)n - 1, 0);
				}
			}
			break;
		case SEL_YOUNG:
			if (ndents) {
				for (r = (cur + 1) % ndents; r != cur; r = (r + 1) % ndents)
					if (pdents[r].flags & FILE_YOUNG)
						break;
				if (pdents[r].flags & FILE_YOUNG)
					move_cursor(r, 0);
			}
			break;
		case SEL_CDHOME:
		case SEL_CDBEGIN:
		case SEL_CDLAST:
		case SEL_CDROOT:
			switch (sel) {
			case SEL_CDHOME:
				dir = homedir;
				break;
			case SEL_CDBEGIN:
				dir = initpath;
				break;
			case SEL_CDLAST:
				dir = lastdir_;
				break;
			default: /* SEL_CDROOT */
				dir = "/";
				break;
			}

			if (!dir || !*dir) {
				printwait("not set", &presel);
				goto nochange;
			}

			if (!xdiraccess(dir)) {
				printwarn(&presel);
				goto nochange;
			}

			if (strcmp(path, dir) == 0) {
				goto nochange;
			}

			/* SEL_CDLAST: dir pointing to lastdir */
			xstrsncpy(newpath, dir, PATH_MAX_LEN);
			lastname_[0] = '\0';
			xstrsncpy(lastdir_, path, PATH_MAX_LEN);
			xstrsncpy(path, newpath, PATH_MAX_LEN);
			clearfilter();
			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_BMOPEN:
			/* select bookmark */
			if (bms_env && *bms_env) {
				/* prompt for key */
				char prompt[64];
				int key;
				snprintf(prompt, sizeof(prompt), "key: ");
				key = get_input(prompt);
				if (key == 27 || key == '\r' || key == '\n' || key == ERR)
					break;
				if (!get_bm_loc(key, newpath)) {
					printwait("invalid key", &presel);
					goto nochange;
				}
				if (!xdiraccess(newpath)) {
					printwarn(&presel);
					goto nochange;
				}
				if (strcmp(path, newpath) == 0)
					break;
				lastname_[0] = '\0';
				xstrsncpy(lastdir_, path, PATH_MAX_LEN);
				xstrsncpy(path, newpath, PATH_MAX_LEN);
				clearfilter();
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
			/* go to bookmarks dir and filter */
			snprintf(newpath, PATH_MAX_LEN, "%s/bookmarks", cfgpath);
			if (!xdiraccess(newpath)) {
				printwarn(&presel);
				goto nochange;
			}
			if (strcmp(path, newpath)) {
				lastname_[0] = '\0';
				xstrsncpy(lastdir_, path, PATH_MAX_LEN);
				xstrsncpy(path, newpath, PATH_MAX_LEN);
				clearfilter();
			}
			g_state.selbm = 1;
			presel = SEL_FILTER;
			goto begin;
		case SEL_REMOTE:
			printwait("not supported", &presel);
			goto nochange;
		case SEL_CYCLE:
		case SEL_CYCLER:
		case SEL_CTX1:
		case SEL_CTX2:
		case SEL_CTX3:
		case SEL_CTX4:
		case SEL_CTX5:
		case SEL_CTX6:
		case SEL_CTX7:
		case SEL_CTX8:
			r = handle_context_switch(sel);
			if (r < 0)
				continue;
			savecurctx(path, ndents ? pdents[cur].name : NULL, r);

			/* Reset the pointers */
			path = g_ctx[r].c_path;
			lastdir_ = g_ctx[r].c_last;
			lastname_ = g_ctx[r].c_name;

			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_MARK:
			free(mark);
			mark = strdup(path);
			printwait(mark, &presel);
			goto nochange;
		case SEL_BMARK:
			/* create bookmark: symlink in bookmarks dir */
			{
				char *name;
				snprintf(newpath, PATH_MAX_LEN, "%s/bookmarks", cfgpath);
				tmp = xreadline(xbasename(path), "name: ");
				if (!tmp || !*tmp)
					break;
				name = tmp;
				{
					char target[PATH_MAX_LEN];
					mkpath(newpath, name, target);
					if (symlink(path, target) == -1)
						printwarn(&presel);
					else
						printwait(target, &presel);
				}
			}
			goto nochange;
		case SEL_FLTR:
			/* Unset filter on 'Esc' */
			presel = SEL_FILTER;
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto nochange;
		case SEL_MFLTR:
			cfg.filtermode ^= 1;
			if (cfg.filtermode) {
				presel = SEL_FILTER;
				goto nochange;
			}
			/* Save current */
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			clearfilter();
			goto begin;
		case SEL_HIDDEN:
			cfg.showhidden ^= 1;
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			if (cfg.filtermode)
				presel = SEL_FILTER;
			goto begin;
		case SEL_DETAIL:
			cfg.showdetail ^= 1;
			cfg.blkorder = 0;
			cfg.apparentsz = 0;
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_STATS:
			if (!ndents)
				break;
			for (;;) {
				r = show_stats_popup(path);
				if (r == 'j') {
					if (cur != ndents - 1)
						move_cursor(cur + 1, 0);
					else if (cfg.rollover)
						move_cursor(0, 0);
					redraw(path);
					refresh();
					continue;
				} else if (r == 'k') {
					if (cur)
						move_cursor(cur - 1, 0);
					else if (cfg.rollover)
						move_cursor(ndents - 1, 0);
					redraw(path);
					refresh();
					continue;
				}
				break;
			}
			break;
		case SEL_CHMODX:
			if (!ndents)
				break;
			mkpath(path, pdents[cur].name, newpath);
			if (lstat(newpath, &sb) == -1) {
				printwarn(&presel);
				goto nochange;
			}
			if (!S_ISREG(sb.st_mode)) {
				printwait("not regular file", &presel);
				goto nochange;
			}
			if (chmod(newpath, (sb.st_mode & 0100) ? (sb.st_mode & ~0111) : (sb.st_mode | 0111)) == -1) {
				printwarn(&presel);
				goto nochange;
			}
			xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_ARCHIVE:
			if (!ndents && !selbufpos)
				break;
			r = get_cur_or_sel();
			if (!r) {
				goto nochange;
			}
			if (r == 's') {
				tmp = xreadline(NULL, "archive [path/]name: ");
			} else
				tmp = xreadline(pdents[cur].name, "archive [path/]name: ");
			if (!tmp || !*tmp)
				break;
			{
				char cmd[32];
				char archive[PATH_MAX_LEN];
				mkpath(path, tmp, archive);
				get_archive_cmd(cmd, tmp);
				if (r == 's') {
					archive_selection(cmd, archive, path);
					clearselection();
				} else {
					char *argv[8];
					int n = 0;
					char cmdbuf[32];
					char *p, *saveptr;
					xstrsncpy(cmdbuf, cmd, sizeof(cmdbuf));
					for (p = strtok_r(cmdbuf, " ", &saveptr); p; p = strtok_r(NULL, " ", &saveptr))
						argv[n++] = p;
					argv[n++] = archive;
					argv[n++] = pdents[cur].name;
					argv[n] = NULL;
					exitcurses();
					{
						pid_t pid = xfork(F_NORMAL);
						if (pid == 0) {
							execvp(argv[0], argv);
							_exit(EXIT_FAILURE);
						}
						join(pid, F_NORMAL);
					}
					refresh();
				}
				xstrsncpy(lastname_, xbasename(archive), NAME_MAX_LEN + 1);
			}
			goto begin;
		case SEL_SORT:
			r = get_input("'a'u/'d'u/'e'xt/'r'ev/'s'z/'t'm/'v'er/'c'lr/'^T'?");
			if (r == 'a' || r == 'd' || r == 'e' || r == 'r' || r == 's' || r == 't' || r == 'v' || r == 'c' || r == CONTROL('T')) {
				set_sort_flags(r);
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
			break;
		case SEL_SEL:
			if (!ndents)
				goto nochange;

			startselection();
			/* Toggle selection status */
			mkpath(path, pdents[cur].name, newpath);
			if (pdents[cur].flags & FILE_SELECTED) {
				pdents[cur].flags &= ~FILE_SELECTED;
				rmfromselbuf(newpath, 0);
			} else {
				pdents[cur].flags |= FILE_SELECTED;
				addtoselbuf(newpath);
			}

			if (g_state.rangesel) {
				g_state.rangesel = 0;
			}

			/* move cursor to next entry if this is not the last entry */
			if (!g_state.stayonsel && (cur != ndents - 1))
				move_cursor((cur + 1) % ndents, 0);
			break;
		case SEL_SELMUL:
			if (!ndents)
				goto nochange;

			startselection();
			g_state.rangesel ^= 1;

			if (g_state.rangesel) { /* Range selection started */
				selstartid = cur;
				continue;
			}

			/* Range selection ended */
			selendid = cur;
			if (selstartid > selendid) {
				r = selstartid;
				selstartid = selendid;
				selendid = r;
			}
			for (r = selstartid; r <= selendid; ++r) {
				if (!(pdents[r].flags & FILE_SELECTED)) {
					mkpath(path, pdents[r].name, newpath);
					pdents[r].flags |= FILE_SELECTED;
					appendfpath(newpath, strlen(newpath) + 1);
					++nselected;
				}
			}
			writeselbuf();
			continue;
		case SEL_SELALL:
		case SEL_SELINV:
			if (!ndents)
				goto nochange;

			startselection();
			if (g_state.rangesel)
				g_state.rangesel = 0;

			if (sel == SEL_SELALL) {
				for (r = 0; r < ndents; ++r) {
					if (!(pdents[r].flags & FILE_SELECTED)) {
						mkpath(path, pdents[r].name, newpath);
						pdents[r].flags |= FILE_SELECTED;
						appendfpath(newpath, strlen(newpath) + 1);
						++nselected;
					}
				}
				writeselbuf();
			} else
				invertselbuf(path);
			continue;
		case SEL_SELEDIT:
			if (!selbufpos) {
				printwait("0 selected", &presel);
				goto nochange;
			}
			{
				int fd = create_tmp_file();
				if (fd == -1)
					break;
				{
					size_t pos = 0;
					while (pos < selbufpos) {
						dprintf(fd, "%s\n", pselbuf + pos);
						pos += strlen(pselbuf + pos) + 1;
					}
				}
				close(fd);
				run_editor(g_tmpfpath);
				selbuf_from_file(g_tmpfpath, false);
				unlink(g_tmpfpath);
				writeselbuf();
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_CP:
		case SEL_MV:
			if (!cpmv_selection(sel == SEL_MV, path)) {
				presel = MSGWAIT;
				goto nochange;
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_CPMVAS:
			if (!selbufpos) {
				printwait("0 selected", &presel);
				goto nochange;
			}
			r = get_input("'c'p/'m'v as?");
			if (r != 'c' && r != 'm')
				break;
			cpmv_as(r == 'm', path);
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_RM:
		case SEL_RMX:
			if (!ndents && !selbufpos)
				break;
			{
				bool use_trash = (sel == SEL_RM) && g_state.trash;
				if (selbufpos && ndents) {
					r = get_input("'c'urrent/'s'el?");
					if (r != 'c' && r != 's')
						break;
				} else if (selbufpos)
					r = 's';
				else
					r = 'c';

				if (r == 's') {
					if (!rmmulstr(NULL, use_trash))
						break;
					clearselection();
				} else {
					mkpath(path, pdents[cur].name, newpath);
					if (!xrm(newpath, use_trash))
						break;
					/* cursor stays at same index */
					if (cur < ndents - 1)
						xstrsncpy(lastname_, pdents[cur + 1].name, NAME_MAX_LEN + 1);
					else if (cur > 0)
						xstrsncpy(lastname_, pdents[cur - 1].name, NAME_MAX_LEN + 1);
					else
						lastname_[0] = '\0';
					goto begin;
				}
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_OPENWITH:
			if (!ndents)
				break;
			mkpath(path, pdents[cur].name, newpath);
			if (g_state.xprompt)
				tmp = xreadline(NULL, "open with: ");
			else
				tmp = getreadline("open with: ");
			if (!tmp || !*tmp)
				break;
			{
				char cmd[CMD_LEN_MAX];
				xstrsncpy(cmd, tmp, sizeof(cmd));
				if (!g_state.xprompt)
					free(tmp);
				r = get_input("['g'ui]/'c'li?");
				if (r == 'c')
					spawn(cmd, newpath, NULL, NULL, F_CLI);
				else if (r == 'g' || r == '\r' || r == '\n')
					spawn(cmd, newpath, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
				else
					break;
			}
			break;
		case SEL_NEW:
			r = get_input("['f'ile]/'d'ir/'s'ym/'h'ard?");
			if (r == '\r' || r == '\n')
				r = 'f';
			if (r != 'f' && r != 'd' && r != 's' && r != 'h')
				break;

			if (r == 'f' || r == 'd') {
				tmp = xreadline(NULL, "[path/]name: ");
				if (!tmp || !*tmp)
					break;
				mkpath(path, tmp, newpath);
				{
					/* create parents */
					char parent[PATH_MAX_LEN];
					xstrsncpy(parent, newpath, PATH_MAX_LEN);
					char *slash = strrchr(parent, '/');
					if (slash && slash != parent) {
						*slash = '\0';
						/* mkdir -p */
						char *p = parent + 1;
						while ((p = strchr(p, '/'))) {
							*p = '\0';
							mkdir(parent, 0755);
							*p = '/';
							++p;
						}
						mkdir(parent, 0755);
					}
				}
				if (access(newpath, F_OK) == 0) {
					printwait("entry exists", &presel);
					goto nochange;
				}
				if (r == 'f') {
					int fd = open(newpath, O_CREAT | O_WRONLY, 0600);
					if (fd == -1) {
						printwarn(&presel);
						goto nochange;
					}
					close(fd);
				} else {
					if (mkdir(newpath, 0755) == -1) {
						printwarn(&presel);
						goto nochange;
					}
				}
				/* cursor on the first component created */
				{
					char *first = tmp;
					while (*first == '/')
						++first;
					char *sl = strchr(first, '/');
					if (sl)
						*sl = '\0';
					xstrsncpy(lastname_, first, NAME_MAX_LEN + 1);
				}
				goto begin;
			}

			/* link(s) */
			{
				int c = get_cur_or_sel();
				if (!c)
					break;
				if (c == 'c') {
					tmp = xreadline(pdents[cur].name, "link suffix [@ for none]: ");
				} else
					tmp = xreadline(NULL, "link suffix [@ for none]: ");
				if (!tmp || !*tmp)
					break;
				/* for current: tmp is the new link name */
				if (c == 'c') {
					char target[PATH_MAX_LEN];
					mkpath(path, pdents[cur].name, target);
					mkpath(path, tmp, newpath);
					int ret = (r == 's') ? symlink(target, newpath) : link(target, newpath);
					if (ret == -1) {
						printwarn(&presel);
						goto nochange;
					}
					xstrsncpy(lastname_, tmp, NAME_MAX_LEN + 1);
				} else {
					size_t pos = 0;
					int cnt = 0;
					char suffix[NAME_MAX_LEN + 1];
					xstrsncpy(suffix, tmp, sizeof(suffix));
					if (!strcmp(suffix, "@"))
						suffix[0] = '\0';
					while (pos < selbufpos) {
						char *src = pselbuf + pos;
						snprintf(newpath, PATH_MAX_LEN, "%s/%s%s", path, xbasename(src), suffix);
						if (((r == 's') ? symlink(src, newpath) : link(src, newpath)) == 0)
							++cnt;
						pos += strlen(src) + 1;
					}
					{
						char msg[64];
						snprintf(msg, sizeof(msg), "%d link%s created", cnt, cnt == 1 ? "" : "s");
						printwait(msg, &presel);
					}
					clearselection();
					if (ndents)
						xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				}
				goto begin;
			}
		case SEL_RENAME:
			if (!ndents)
				break;
			tmp = xreadline(pdents[cur].name, "");
			if (!tmp || !*tmp)
				break;
			if (!strcmp(tmp, pdents[cur].name))
				break;
			mkpath(path, tmp, newpath);
			{
				char oldpath[PATH_MAX_LEN];
				mkpath(path, pdents[cur].name, oldpath);
				if (access(newpath, F_OK) == 0) {
					r = get_input("overwrite?");
					if (!xconfirm(r))
						break;
				}
				if (rename(oldpath, newpath) == -1) {
					printwarn(&presel);
					goto nochange;
				}
				xstrsncpy(lastname_, xbasename(newpath), NAME_MAX_LEN + 1);
			}
			goto begin;
		case SEL_RENAMEMUL:
			{
				/* batch rename via editor */
				int fd = create_tmp_file();
				if (fd == -1)
					break;
				{
					char **names = NULL;
					int n = 0;
					if (selbufpos) {
						size_t pos = 0;
						while (pos < selbufpos) {
							dprintf(fd, "%s\n", pselbuf + pos);
							names = xrealloc(names, (n + 1) * sizeof(char *));
							names[n++] = strdup(pselbuf + pos);
							pos += strlen(pselbuf + pos) + 1;
						}
					} else {
						for (r = 0; r < ndents; ++r) {
							dprintf(fd, "%s\n", pdents[r].name);
							names = xrealloc(names, (n + 1) * sizeof(char *));
							names[n++] = strdup(pdents[r].name);
						}
					}
					close(fd);
					run_editor(g_tmpfpath);
					{
						FILE *fp = fopen(g_tmpfpath, "r");
						char line[PATH_MAX_LEN];
						int i = 0, renamed = 0;
						if (fp) {
							while (fgets(line, sizeof(line), fp)) {
								size_t l = strlen(line);
								while (l && (line[l - 1] == '\n' || line[l - 1] == '\r'))
									line[--l] = '\0';
								if (i >= n)
									break;
								if (*line && strcmp(line, names[i])) {
									char src[PATH_MAX_LEN], dst[PATH_MAX_LEN];
									mkpath(path, names[i], src);
									mkpath(path, line, dst);
									exitcurses();
									{
										char *argv[6] = {"mv", "-i", "--", src, dst, NULL};
										pid_t pid = xfork(F_NORMAL);
										if (pid == 0) {
											execvp(argv[0], argv);
											_exit(EXIT_FAILURE);
										}
										join(pid, F_NORMAL);
									}
									refresh();
									++renamed;
								} else if (!*line) {
									/* empty line: remove */
								}
								++i;
							}
							fclose(fp);
						}
						(void)renamed;
					}
					for (int k = 0; k < n; ++k)
						free(names[k]);
					free(names);
					unlink(g_tmpfpath);
				}
				if (selbufpos)
					clearselection();
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			}
			goto begin;
		case SEL_UMOUNT:
			printwait("not supported", &presel);
			goto nochange;
		case SEL_HELP:
			show_help(path);
			if (cfg.filtermode)
				presel = SEL_FILTER;
			continue;
		case SEL_AUTONEXT:
			g_state.autonext ^= 1;
			printwait(g_state.autonext ? "auto-advance on" : "auto-advance off", &presel);
			goto nochange;
		case SEL_EDIT:
			if (!ndents)
				break;
			mkpath(path, pdents[cur].name, newpath);
			spawn(get_editor(), newpath, NULL, NULL, F_CLI);
			continue;
		case SEL_PLUGIN:
		case SEL_PLUGKEY:
			printwait("plugin not found", &presel);
			goto nochange;
		case SEL_SELSIZE:
			{
				/* total size of listed selected entries */
				off_t total = 0;
				int n = 0;
				for (r = 0; r < ndents; ++r)
					if (pdents[r].flags & FILE_SELECTED) {
						total += cfg.blkorder ? (off_t)pdents[r].blocks << 9 : pdents[r].size;
						++n;
					}
				if (!n) {
					printwait("0 selected", &presel);
					goto nochange;
				}
				{
					char msg[64];
					snprintf(msg, sizeof(msg), "%d selected: %s", n, coolsize(total));
					printwait(msg, &presel);
				}
			}
			goto nochange;
		case SEL_SHELL:
			run_shell(path);
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_LAUNCH:
			tmp = g_state.xprompt ? xreadline(NULL, "launch: ") : getreadline("launch: ");
			if (!tmp || !*tmp)
				break;
			{
				char cmd[CMD_LEN_MAX];
				xstrsncpy(cmd, tmp, sizeof(cmd));
				if (!g_state.xprompt)
					free(tmp);
				spawn(cmd, NULL, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
			}
			break;
		case SEL_PROMPT:
			{
				char *shell = get_shell();
				if (ndents) {
					setenv("NNN_CUR", pdents[cur].name, 1);
				}
				tmp = g_state.xprompt ? xreadline(NULL, "> ") : getreadline("> ");
				if (!tmp || !*tmp)
					break;
				{
					char cmd[CMD_LEN_MAX];
					xstrsncpy(cmd, tmp, sizeof(cmd));
					if (!g_state.xprompt)
						free(tmp);
					spawn(shell, "-c", cmd, NULL, F_CLI | F_CONFIRM);
				}
			}
			if (ndents)
				xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
			goto begin;
		case SEL_LOCK:
			{
				char *locker = lockcmd_env;
				if (locker && *locker)
					spawn(locker, NULL, NULL, NULL, F_CLI);
				else if (is_executable_in_path("vlock"))
					spawn("vlock", NULL, NULL, NULL, F_CLI);
				else if (is_executable_in_path("bashlock"))
					spawn("bashlock", NULL, NULL, NULL, F_CLI);
				else {
					printwait("missing locker", &presel);
					goto nochange;
				}
			}
			break;
		case SEL_SESSIONS:
			r = get_input("'s'ave/'l'oad/'r'estore?");
			if (r != 's' && r != 'l' && r != 'r')
				break;
			printwait("not supported", &presel);
			goto nochange;
		case SEL_EXPORT:
			{
				int fd = create_tmp_file();
				if (fd == -1)
					break;
				for (r = 0; r < ndents; ++r)
					dprintf(fd, "%s\n", pdents[r].name);
				close(fd);
				run_editor(g_tmpfpath);
				unlink(g_tmpfpath);
			}
			break;
		case SEL_TIMETYPE:
			r = get_input("'a'ccess / 'c'hange / 'm'od [m]");
			if (r == 'a' || r == 'c' || r == 'm' || r == '\r' || r == '\n') {
				if (r == 'a')
					cfg.timetype = T_ACCESS;
				else if (r == 'c')
					cfg.timetype = T_CHANGE;
				else
					cfg.timetype = T_MOD;
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
			break;
		case SEL_QUITCTX:
			{
				int ctx = cfg.curctx;
				/* Find the next active context */
				g_ctx[ctx].c_cfg.ctxactive = 0;
				for (r = (ctx + 1) & (CTX_MAX - 1); r != ctx; r = (r + 1) & (CTX_MAX - 1))
					if (g_ctx[r].c_cfg.ctxactive)
						break;
				if (r == ctx) {
					/* last context: quit */
					if (g_state.picker && selbufpos) {
						g_state.picked = 1;
					}
					return true;
				}
				/* switch to context r */
				{
					settings tmpcfg = g_ctx[r].c_cfg;
					tmpcfg.curctx = r;
					cfg = tmpcfg;
					path = g_ctx[r].c_path;
					lastdir_ = g_ctx[r].c_last;
					lastname_ = g_ctx[r].c_name;
				}
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
		case SEL_QUITCD:
			g_state.forcequit = 1;
			write_lastdir(path, NULL);
			return true;
		case SEL_QUIT:
			if (count_active_ctx() > 1 && g_state.quitconfirm) {
				r = get_input("Quit all contexts?");
				if (!xconfirm(r))
					break;
			}
			return true;
		case SEL_QUITERR:
			if (g_state.picker)
				g_state.picked = 1;
			g_state.forcequit = 1;
			return true;
		case SEL_FIFO:
			if (fifopath && ndents)
				notify_fifo(true, path);
			goto nochange;
		case SEL_UNFLTRQUIT:
			/* Alt+Esc: unfilter and quit context */
			if (filterset()) {
				clearfilter();
				if (ndents)
					xstrsncpy(lastname_, pdents[cur].name, NAME_MAX_LEN + 1);
				goto begin;
			}
			sel = SEL_QUITCTX;
			{
				int ctx = cfg.curctx;
				g_ctx[ctx].c_cfg.ctxactive = 0;
				for (r = (ctx + 1) & (CTX_MAX - 1); r != ctx; r = (r + 1) & (CTX_MAX - 1))
					if (g_ctx[r].c_cfg.ctxactive)
						break;
				if (r == ctx)
					return true;
				{
					settings tmpcfg = g_ctx[r].c_cfg;
					tmpcfg.curctx = r;
					cfg = tmpcfg;
					path = g_ctx[r].c_path;
					lastdir_ = g_ctx[r].c_last;
					lastname_ = g_ctx[r].c_name;
				}
				if (cfg.filtermode)
					presel = SEL_FILTER;
				goto begin;
			}
		case SEL_FILTER:
			/* filter prompt */
			r = filterentries(path, lastname_);
			if (r == KEY_F(63)) { /* Alt+Esc */
				presel = 0;
				sel = SEL_UNFLTRQUIT;
				if (filterset()) {
					clearfilter();
					goto begin;
				}
				/* quit context */
				{
					int ctx = cfg.curctx;
					g_ctx[ctx].c_cfg.ctxactive = 0;
					for (r = (ctx + 1) & (CTX_MAX - 1); r != ctx; r = (r + 1) & (CTX_MAX - 1))
						if (g_ctx[r].c_cfg.ctxactive)
							break;
					if (r == ctx)
						return true;
					{
						settings tmpcfg = g_ctx[r].c_cfg;
						tmpcfg.curctx = r;
						cfg = tmpcfg;
						path = g_ctx[r].c_path;
						lastdir_ = g_ctx[r].c_last;
						lastname_ = g_ctx[r].c_name;
					}
					if (cfg.filtermode)
						presel = SEL_FILTER;
					goto begin;
				}
			}
			if (r == KEY_F(62)) { /* Alt+key */
				presel = 0;
				goto nochange;
			}
			if (r == 27) {
				/* Esc: exit prompt */
				if (g_state.selbm) {
					g_state.selbm = 0;
				}
				presel = 0;
				break;
			}
			if (r == KEY_ENTER || r == '\r' || r == '\n') {
				presel = SEL_OPEN;
				/* process via the open path with key translation */
				{
					/* emulate SEL_OPEN */
					sel = SEL_OPEN;
				}
				/* fallthrough into switch again by looping */
				{
					int saved = presel;
					presel = 0;
					/* handle open inline */
					if (!ndents)
						goto nochange;
					mkpath(path, pdents[cur].name, newpath);
					if (pdents[cur].flags & DIR_OR_DIRLNK) {
						if (!xdiraccess(newpath)) {
							printwarn(&presel);
							goto nochange;
						}
						xstrsncpy(lastdir_, path, PATH_MAX_LEN);
						xstrsncpy(path, newpath, PATH_MAX_LEN);
						lastname_[0] = '\0';
						clearfilter();
						if (cfg.filtermode)
							presel = SEL_FILTER;
						goto begin;
					}
					(void)saved;
					if (g_state.picker) {
						selbufpos = 0;
						appendfpath(newpath, strlen(newpath) + 1);
						nselected = 1;
						g_state.picked = 1;
						return true;
					}
					if (S_ISREG(pdents[cur].mode) && !pdents[cur].size) {
						printwait("empty! edit/open with", &presel);
						goto nochange;
					}
					if (cfg.useeditor && is_textfile(newpath))
						spawn(get_editor(), newpath, NULL, NULL, F_CLI);
					else if (cfg.cliopener)
						spawn(get_opener(), newpath, NULL, NULL, F_CLI);
					else
						spawn(get_opener(), newpath, NULL, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
					if (cfg.filtermode)
						presel = SEL_FILTER;
					continue;
				}
			}
			/* other keys: process in main loop */
			{
				/* translate key r to action */
				uint_t i;
				int act = 0;
				if (r == KEY_RESIZE) {
					goto begin;
				}
				for (i = 0; bindings[i].sym; ++i)
					if (r == bindings[i].sym) {
						act = bindings[i].act;
						break;
					}
				if (!act)
					goto nochange;
				presel = act;
				goto nochange;
			}
		default:
			if (xlines != LINES || xcols != COLS) {
				goto begin;
			}
			goto nochange;
		} /* switch (sel) */
	}
	(void)rangesel; (void)rundir; (void)runfile; (void)watch; (void)dir_changed;
	return false;
