static char *xdirname(const char *path)
{
	static char buf[PATH_MAX_LEN];
	char *last_slash;

	xstrsncpy(buf, path, PATH_MAX_LEN);
	last_slash = strrchr(buf, '/');
	if (!last_slash) {
		buf[0] = '.';
		buf[1] = '\0';
		return buf;
	}
	if (last_slash == buf)
		buf[1] = '\0';
	else
		*last_slash = '\0';
	return buf;
}

/* ---------------- setup ---------------- */

static bool setup_config(void)
{
	size_t r, len;
	char *xdgcfg = getenv("XDG_CONFIG_HOME");
	bool xdg = false;

	/* Set up configuration file paths */
	if (xdgcfg && xdgcfg[0]) {
		if (xdgcfg[0] == '~') {
			r = xstrsncpy(g_buf, homedir, PATH_MAX_LEN);
			xstrsncpy(g_buf + r - 1, xdgcfg + 1, PATH_MAX_LEN);
			xdgcfg = g_buf;
		}
		len = strlen(xdgcfg) + strlen("/nnn/bookmarks") + 1;
		xdg = true;
	} else
		len = strlen(homedir) + strlen("/.config/nnn/bookmarks") + 1;

	cfgpath = (char *)malloc(len);
	plgpath = (char *)malloc(len);
	if (!cfgpath || !plgpath) {
		fprintf(stderr, "%s\n", strerror(errno));
		return false;
	}

	if (xdg) {
		xstrsncpy(cfgpath, xdgcfg, len);
		r = len - strlen("/nnn/bookmarks");
	} else {
		r = xstrsncpy(cfgpath, homedir, len);
		/* Create ~/.config */
		xstrsncpy(cfgpath + r - 1, "/.config", len - r);
		mkdir(cfgpath, 0777);
		r += 8; /* length of "/.config" */
	}

	/* Create ~/.config/nnn */
	xstrsncpy(cfgpath + r - 1, "/nnn", len - r);
	mkdir(cfgpath, 0777);
	/* Create bookmarks, sessions, mounts and plugins directories */
	{
		static const char * const subdirs[] = {"bookmarks", "sessions", "mounts", "plugins"};
		for (int i = 0; i < 4; ++i) {
			mkpath(cfgpath, subdirs[i], plgpath);
			mkdir(plgpath, 0777);
		}
	}
	mkpath(cfgpath, "plugins", plgpath);
	/* cfgpath now ends with /nnn */

	/* Set selection file path */
	if (!g_state.picker) {
		char *env_sel = getenv("NNN_SEL");

		selpath = env_sel ? strdup(env_sel) : (char *)malloc(len + 3);
		if (!selpath) {
			fprintf(stderr, "%s\n", strerror(errno));
			return false;
		}
		if (!env_sel) {
			r = xstrsncpy(selpath, cfgpath, len + 3);
			xstrsncpy(selpath + r - 1, "/.selection", len + 3 - r);
		}
	}

	return true;
}

