		" -x      notis, selection sync, xterm title\n"
		" -z      in order fuzzy filters\n"
		" -0      null separator in picker mode\n"
		" -h      show help\n\n"
		"v%s\nBSD 2-Clause\nhttps://github.com/jarun/nnn\n", VERSION);
}

/* list mode: read NUL separated paths from stdin, create a tree of symlinks in a temp dir */
static char *load_input(int fd, const char *path)
{
	size_t i, chunk_count = 1, chunk = 512 * 1024 /* 512 KiB chunk size */, entries = 0;
	char *input = malloc(sizeof(char) * chunk), *tmpdir = NULL;
	char cwd[PATH_MAX_LEN], *next;
	size_t offsets[1024 * 64];
	char **paths = NULL;
	ssize_t input_read, total_read = 0, off = 0;
	int msgnum = 0;

	if (!input) {
		fprintf(stderr, "%s\n", strerror(errno));
		return NULL;
	}

	if (!path) {
		if (!getcwd(cwd, PATH_MAX_LEN)) {
			free(input);
			return NULL;
		}
	} else
		xstrsncpy(cwd, path, PATH_MAX_LEN);

	while (chunk_count < 512) {
		input_read = read(fd, input + total_read, chunk);
		if (input_read < 0) {
			if (errno == EINTR)
				continue;
			fprintf(stderr, "%s\n", strerror(errno));
			goto malloc_1;
		}

		if (input_read == 0)
			break;

		total_read += input_read;
		++chunk_count;

		while (off < total_read) {
			next = memchr(input + off, '\0', total_read - off) + 1;
			if (next == (char *)1)
				break;

			if (next - input == off + 1) {
				off = next - input;
				continue;
			}

			if (entries == 1024 * 64) {
				fprintf(stderr, "too many entries\n");
				goto malloc_1;
			}

			offsets[entries++] = off;
			off = next - input;
		}

		if (chunk_count == 512) {
			fprintf(stderr, "too much input\n");
			goto malloc_1;
		}

		/* We don't need to allocate another chunk */
		if (chunk_count == (size_t)(total_read - input_read) / chunk)
			continue;

		chunk_count = total_read / chunk;
		if (total_read % chunk)
			++chunk_count;

		input = xrealloc(input, (chunk_count + 1) * chunk);
		if (!input)
			return NULL;
	}

	if (off != total_read) {
		if (entries == 1024 * 64) {
			fprintf(stderr, "too many entries\n");
			goto malloc_1;
		}

		offsets[entries++] = off;
	}

	if (!entries) {
		fprintf(stderr, "0 entries\n");
		goto malloc_1;
	}

	input[total_read] = '\0';

	paths = malloc(entries * sizeof(char *));
	if (!paths)
		goto malloc_1;

	for (i = 0; i < entries; ++i)
		paths[i] = input + offsets[i];

	{
		char prefix[PATH_MAX_LEN] = {0};
		size_t valid = 0;
		for (i = 0; i < entries; ++i) {
			char *ap = abspath(paths[i], cwd, NULL);
			if (!ap)
				continue;
			if (access(ap, F_OK) == -1) {
				free(ap);
				continue;
			}
			paths[valid++] = ap;
			common_prefix(ap, prefix);
		}
		entries = valid;
		if (!entries) {
			fprintf(stderr, "0 entries\n");
			goto malloc_2;
		}
		/* If the common prefix is a file (single entry), use its dir */
		{
			struct stat sb;
			if (entries == 1 || (stat(prefix, &sb) == 0 && !S_ISDIR(sb.st_mode))) {
				char *s = strrchr(prefix, '/');
				if (s && s != prefix)
					*s = '\0';
				else if (s)
					prefix[1] = '\0';
			}
		}

		listroot = strdup(prefix);

		/* create temp dir */
		{
			size_t len = xstrsncpy(g_tmpdir + 0, g_tmpdir, PATH_MAX_LEN);
			(void)len;
			snprintf(g_buf, CMD_LEN_MAX, "%s/nnnXXXXXX", g_tmpdir);
			tmpdir = mkdtemp(g_buf);
			if (!tmpdir) {
				fprintf(stderr, "%s\n", strerror(errno));
				goto malloc_2;
			}
			tmpdir = strdup(tmpdir);
			listpath = tmpdir;
		}

		for (i = 0; i < entries; ++i) {
			char *rel = paths[i] + strlen(prefix);
			char linkpath[PATH_MAX_LEN];
			if (*rel == '/')
				++rel;
			if (!*rel)
				continue;
			snprintf(linkpath, PATH_MAX_LEN, "%s/%s", tmpdir, rel);
			/* create parent dirs */
			{
				char *p = linkpath + strlen(tmpdir) + 1;
				while ((p = strchr(p, '/'))) {
					*p = '\0';
					mkdir(linkpath, 0755);
					*p = '/';
					++p;
				}
			}
			if (symlink(paths[i], linkpath) == -1) {
				++msgnum;
			}
			free(paths[i]);
		}
	}

	free(paths);
	free(input);
	return tmpdir;

malloc_2:
	free(paths);
malloc_1:
	free(input);
	return NULL;
}

static void cleanup_listpath(void)
{
	if (listpath) {
		spawn("rm", "-rf", listpath, NULL, F_SILENT | F_NOWAIT);
	}
}

static void check_key_collision_unused(void) {}

int main(int argc, char *argv[])
{
	char *arg = NULL;
	char *session = NULL;
	int fd, opt, sort = 0, pkey = '\0';
	char *tmpdir_env;
	bool from_env = false;
	char *env_opts = getenv("NNN_OPTS");
	int env_opts_id = env_opts ? (int)strlen(env_opts) : -1;
	char *bmkey = NULL;
	char *picker_file = NULL;

	g_state.quitconfirm = 1;
	g_state.autonext = 1;
	cfg.rollover = 1;

	while ((opt = (env_opts_id > 0
		       ? env_opts[--env_opts_id]
		       : getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKl:nNop:P:QrRs:St:T:uUVxzZh0"))) != -1) {
		from_env = env_opts_id > 0 || (env_opts_id == 0 && env_opts && *env_opts);
		if (env_opts_id >= 0 && env_opts_id < (int)strlen(env_opts ? env_opts : "")) {
		}
		switch (opt) {
		case 'a':
			g_state.autofifo = 1;
			break;
		case 'A':
			cfg.autoenter = 0;
			break;
		case 'b':
			if (env_opts_id < 0)
				bmkey = optarg;
			break;
		case 'B':
			g_state.usebsdtar = 1;
			break;
		case 'c':
			cfg.cliopener = 1;
			break;
		case 'C':
			g_state.oldcolor = 1;
			break;
		case 'd':
			cfg.showdetail = 1;
			break;
		case 'D':
			g_state.dirctx = 1;
			break;
		case 'e':
			cfg.useeditor = 1;
			break;
		case 'E':
			cfg.waitedit = 1;
			break;
		case 'f':
			g_state.usehistory = 1;
			break;
		case 'F':
			if (env_opts_id < 0) {
				fd = atoi(optarg);
				if ((fd < 0) || (fd > 1))
					return 1;
				g_state.fifomode = fd;
			}
			break;
		case 'g':
			cfg.regex = 1;
			flt_type = FLT_REG;
			break;
		case 'H':
			cfg.showhidden = 1;
			break;
		case 'i':
			cfg.fileinfo = 1;
			break;
		case 'J':
			g_state.stayonsel = 1;
			break;
		case 'K':
			g_state.keycollide = 1;
			break;
		case 'l':
			if (env_opts_id < 0)
				scroll_lines = atoi(optarg);
			break;
		case 'n':
			cfg.filtermode = 1;
			break;
		case 'N':
			g_state.xprompt = 1;
			break;
		case 'o':
			cfg.nonavopen = 1;
			break;
		case 'p':
			if (env_opts_id >= 0)
				break;
			g_state.picker = 1;
			picker_file = optarg;
			break;
		case 'P':
			if (env_opts_id < 0 && !optarg[1])
				pkey = (uchar_t)optarg[0];
			break;
		case 'Q':
			g_state.quitconfirm = 0;
			break;
		case 'r':
			break;
		case 'R':
			cfg.rollover = 0;
			break;
		case 's':
			if (env_opts_id < 0)
				session = optarg;
			break;
		case 'S':
			g_state.prstssn = 1;
			if (!session)
				session = "@";
			break;
		case 't':
			if (env_opts_id < 0)
				idletimeout = atoi(optarg);
			break;
		case 'T':
			if (env_opts_id < 0)
				sort = (uchar_t)optarg[0];
			break;
		case 'u':
			cfg.prefersel = 1;
			break;
		case 'U':
			g_state.uidgid = 1;
			break;
		case 'V':
			fprintf(stdout, "%s\n", VERSION);
			return 0;
		case 'x':
			cfg.x11 = 1;
			break;
		case 'z':
			flt_type = FLT_FZY;
			break;
		case '0':
			g_state.nullsep = 1;
			break;
		case 'h':
			usage_real();
			return 0;
		default:
			usage_real();
			return 1;
		}
		if (env_opts_id == 0)
			env_opts_id = -1;
	}
	(void)from_env;

	/* Confirm we are in a terminal */
	if (!g_state.picker && !isatty(STDOUT_FILENO)) {
		fprintf(stderr, "stdout is not a tty\n");
		return 1;
	}

	/* Now we are in path list mode */
	if (!isatty(STDIN_FILENO)) {
		/* This is the same as listpath */
		initpath = load_input(STDIN_FILENO, NULL);
		if (!initpath)
			return 1;

		/* We return to tty */
		if (!freopen("/dev/tty", "r", stdin)) {
			fprintf(stderr, "%s\n", strerror(errno));
			return 1;
		}
	}

	homedir = getenv("HOME");
	if (!homedir) {
		fprintf(stderr, "set HOME\n");
		return 1;
	}

	tmpdir_env = getenv("TMPDIR");
	if (tmpdir_env && *tmpdir_env)
		xstrsncpy(g_tmpdir, tmpdir_env, PATH_MAX_LEN);
	else
		xstrsncpy(g_tmpdir, "/tmp", PATH_MAX_LEN);

	if (!setup_config())
		return 1;

	if (g_state.picker && picker_file) {
		if (picker_file[0] == '-' && !picker_file[1])
			g_state.pickraw = 1;
		else {
			selpath = realpath(picker_file, NULL);
			if (!selpath) {
				/* file may not exist yet */
				char cwd[PATH_MAX_LEN];
				if (!getcwd(cwd, PATH_MAX_LEN))
					return 1;
				selpath = abspath(picker_file, cwd, NULL);
			}
		}
	}

	/* Get custom opener, if set */
	bms_env = getenv("NNN_BMS");
	plug_env = getenv("NNN_PLUG");
	order_env = getenv("NNN_ORDER");
	lockcmd_env = getenv("NNN_LOCKER");
	g_tmpfile_env = getenv("NNN_TMPFILE");
	fifopath = getenv("NNN_FIFO");
	g_selpath_env = getenv("NNN_SEL");
	{
		char *trash = getenv("NNN_TRASH");
		if (trash && *trash) {
			g_state.trash = (uchar_t)(trash[0] - '0');
			if (g_state.trash > 2)
				g_state.trash = 1;
		}
	}
	if (bms_env) {
		/* build "key: path" lines for help */
		size_t l = strlen(bms_env);
		char *b = bms_env;
		bookmark_keys = malloc(l * 3 + 4);
		bookmark_keys[0] = '\0';
		while (*b) {
			char *end = strchr(b, ';');
			size_t len = end ? (size_t)(end - b) : strlen(b);
			if (len >= 2 && b[1] == ':') {
				strcat(bookmark_keys, " ");
				strncat(bookmark_keys, b, 1);
				strcat(bookmark_keys, ": ");
				strncat(bookmark_keys, b + 2, len - 2);
				strcat(bookmark_keys, "\n");
			}
			if (!end)
				break;
			b = end + 1;
		}
		/* remove trailing newline */
		l = strlen(bookmark_keys);
		if (l && bookmark_keys[l - 1] == '\n')
			bookmark_keys[l - 1] = '\0';
	}

	if (!initpath) {
		if (bmkey) {
			initpath = malloc(PATH_MAX_LEN);
			if (!get_bm_loc(bmkey[0], initpath)) {
				fprintf(stderr, "%s\n", "key not found");
				return 1;
			}
		} else if (arg || optind < argc) {
			char cwd[PATH_MAX_LEN];
			struct stat sb;
			arg = argv[optind];
			if (!getcwd(cwd, PATH_MAX_LEN))
				return 1;
			initpath = abspath(arg, cwd, NULL);
			if (!initpath) {
				fprintf(stderr, "%s\n", strerror(errno));
				return 1;
			}
			/* remove trailing slashes */
			{
				size_t l = strlen(initpath);
				bool trailing = false;
				while (l > 1 && initpath[l - 1] == '/') {
					initpath[--l] = '\0';
					trailing = true;
				}
				if (stat(initpath, &sb) == -1) {
					/* doesn't exist: create */
					size_t al = strlen(arg);
					bool wantdir = trailing || (al && arg[al - 1] == '/');
					if (wantdir) {
						char tmp[PATH_MAX_LEN];
						xstrsncpy(tmp, initpath, PATH_MAX_LEN);
						char *p = tmp + 1;
						while ((p = strchr(p, '/'))) {
							*p = '\0';
							mkdir(tmp, 0755);
							*p = '/';
							++p;
						}
						if (mkdir(tmp, 0755) == -1 && errno != EEXIST) {
							fprintf(stderr, "%s\n", strerror(errno));
							return 1;
						}
					} else {
						/* create parent dirs, open parent, prompt to create file */
						char tmp[PATH_MAX_LEN];
						xstrsncpy(tmp, initpath, PATH_MAX_LEN);
						char *slash = strrchr(tmp, '/');
						if (slash && slash != tmp) {
							*slash = '\0';
							char *p = tmp + 1;
							while ((p = strchr(p, '/'))) {
								*p = '\0';
								mkdir(tmp, 0755);
								*p = '/';
								++p;
							}
							mkdir(tmp, 0755);
						}
						if (!xdiraccess(tmp) && !(slash == tmp)) {
							fprintf(stderr, "%s\n", strerror(errno));
							return 1;
						}
						g_state.initfile = 1;
						xstrsncpy(g_ctx[0].c_name, xbasename(initpath), NAME_MAX_LEN + 1);
						if (slash == tmp)
							tmp[1] = '\0';
						xstrsncpy(initpath, tmp, PATH_MAX_LEN);
					}
				} else if (!S_ISDIR(sb.st_mode)) {
					/* file: open parent with cursor on it */
					xstrsncpy(g_ctx[0].c_name, xbasename(initpath), NAME_MAX_LEN + 1);
					{
						char *d = xdirname(initpath);
						xstrsncpy(initpath, d, PATH_MAX_LEN);
					}
				}
			}
		} else {
			initpath = malloc(PATH_MAX_LEN);
			if (!getcwd(initpath, PATH_MAX_LEN)) {
				fprintf(stderr, "%s\n", strerror(errno));
				return 1;
			}
		}
	}

	if (!xdiraccess(initpath)) {
		fprintf(stderr, "%d: %s\n", getpid(), strerror(errno));
		return 1;
	}

	/* Set locale */
	setlocale(LC_ALL, "");

	/* Sort */
	if (sort)
		set_sort_flags_from_opt((char)sort);

	/* inotify */
	inotify_fd = inotify_init1(IN_NONBLOCK);

	/* Ignore/handle certain signals */
	{
		struct sigaction act = {.sa_handler = sigint_handler};
		sigaction(SIGINT, &act, NULL);
		signal(SIGQUIT, SIG_IGN);
		signal(SIGPIPE, SIG_IGN);
	}

	/* Prefill the selection buffer from the selection file (persistent) */
	if (!g_state.picker && selpath && access(selpath, R_OK) == 0) {
		selbuf_from_file(selpath, true);
		if (!selbufpos)
			nselected = 0;
	}

	if (!initcurses())
		return 1;

	if (!set_colors()) {
		exitcurses();
		return 1;
	}

	getmaxyx(stdscr, xlines, xcols);

	{
		bool ret = browse(initpath, session, pkey);
		exitcurses();

		if (g_state.picker) {
			if (g_state.picked && selbufpos) {
				/* output */
				size_t pos = 0;
				FILE *out = stdout;
				int ofd = -1;
				if (!g_state.pickraw) {
					ofd = open(selpath, O_WRONLY | O_CREAT | O_TRUNC, 0600);
					if (ofd == -1)
						out = NULL;
				}
				while (pos < selbufpos) {
					size_t l = strlen(pselbuf + pos);
					if (g_state.pickraw) {
						fwrite(pselbuf + pos, 1, l, out);
						fputc(g_state.nullsep ? '\0' : '\n', out);
					} else if (ofd != -1) {
						if (write(ofd, pselbuf + pos, l) == -1) {}
						if (write(ofd, g_state.nullsep ? "" : "\n", 1) == -1) {}
					}
					pos += l + 1;
				}
				if (ofd != -1)
					close(ofd);
				if (g_state.pickraw)
					fflush(stdout);
			}
		} else if (g_state.forcequit && !g_state.picked) {
			/* 'Q' outside picker mode: print selection to stdout */
			if (selbufpos) {
				size_t pos = 0;
				while (pos < selbufpos) {
					size_t l = strlen(pselbuf + pos);
					fwrite(pselbuf + pos, 1, l, stdout);
					fputc('\n', stdout);
					pos += l + 1;
				}
			}
		} else if (selpath) {
			/* remove the selection file on normal quit */
			unlink(selpath);
		}

		cleanup_listpath();
		(void)ret;
	}

	return (g_state.picker && g_state.forcequit) ? 1 : 0;
}
