		    || (header.fltrln[i] > 0 && write(fd, g_ctx[i].c_fltr, header.fltrln[i]) != header.fltrln[i])
		    || (header.pathln[i] > 0 && write(fd, g_ctx[i].c_path, header.pathln[i]) != header.pathln[i]))
