static bool load_session(const char *sname, char **path, char **lastdir_, char **lastname_, bool restore)
{
	int fd, i = 0;
	session_header_t header;
	bool has_loaded_dynamically = !(sname || restore);
	bool status = (sname && g_state.picker); /* Picker mode: ignore session */
	char ssnpath[PATH_MAX_LEN];
	char spath[PATH_MAX_LEN];

	mkpath(cfgpath, "sessions", ssnpath);

	if (!restore) {
		if (!sname) {
			sname = xreadline(NULL, "session name: ");
			if (!sname || !*sname)
				return false;
		}
	} else
		sname = "@";

	mkpath(ssnpath, sname, spath);

	fd = open(spath, O_RDONLY, 0666);
	if (fd == -1) {
		if (!status) {
			printmsg("invalid session");
		}
		return false;
	}

	status = false;

	if ((read(fd, &header, sizeof(header)) != (ssize_t)sizeof(header)) || (header.ver != 1)
	    || (read(fd, &cfg, sizeof(cfg)) != (ssize_t)sizeof(cfg)))
		goto END;

	g_ctx[cfg.curctx].c_cfg.ctxactive = 0;
	for (; i < CTX_MAX; ++i)
		if ((read(fd, &g_ctx[i].c_cfg, sizeof(settings)) != (ssize_t)sizeof(settings))
		    || (read(fd, &g_ctx[i].color, sizeof(uint_t)) != (ssize_t)sizeof(uint_t))
		    || (header.nameln[i] > 0 && read(fd, g_ctx[i].c_name, header.nameln[i]) != header.nameln[i])
		    || (header.lastln[i] > 0 && read(fd, g_ctx[i].c_last, header.lastln[i]) != header.lastln[i])
		    || (header.fltrln[i] > 0 && read(fd, g_ctx[i].c_fltr, header.fltrln[i]) != header.fltrln[i])
		    || (header.pathln[i] > 0 && read(fd, g_ctx[i].c_path, header.pathln[i]) != header.pathln[i]))
			goto END;

	*path = g_ctx[cfg.curctx].c_path;
	*lastdir_ = g_ctx[cfg.curctx].c_last;
	*lastname_ = g_ctx[cfg.curctx].c_name;
	set_colors();
	status = true;

END:
	close(fd);

	if (!status) {
		printmsg("failed!");
	} else if (restore)
		unlink(spath);

	(void)has_loaded_dynamically;
	return status;
}

