static bool run_plugin(char **path, char *file, char *runfile, char **lastname_, char **lastdir_)
{
	bool cmd_as_plugin = false;
	uchar_t flags = 0;
	char *plugin = file;
	char tmppath[PATH_MAX_LEN];
	int fd;
	size_t len;

	if (!plugin)
		return false;

	/* Commands as plugins: prefixed with _ */
	if (*plugin == '_') {
		cmd_as_plugin = true;
		++plugin;
	}

	/* Output is a path to cd into: prefixed with | */
	bool outdir = false;
	if (*plugin == '|') {
		outdir = true;
		++plugin;
	}

	if (!*plugin)
		return false;

	/* GUI apps: suffixed with * (don't wait) */
	len = strlen(plugin);
	if (len && plugin[len - 1] == '*') {
		flags |= F_NOWAIT | F_NOTRACE;
		plugin[len - 1] = '\\0';
	}

	/* create temp file for output */
	fd = create_tmp_file();
	if (fd == -1)
		return false;
	close(fd);
	xstrsncpy(tmppath, g_tmpfpath, PATH_MAX_LEN);

	setenv("NNN_PIPE", tmppath, 1);
	if (runfile && *runfile)
		setenv("NNN_INCLUDE_HIDDEN", cfg.showhidden ? "1" : "0", 1);
	setenv("NNN_INCLUDE_HIDDEN", cfg.showhidden ? "1" : "0", 1);
	setenv("NNN_PREFER_SELECTION", cfg.prefersel ? "1" : "0", 1);

	if (cmd_as_plugin) {
		char cmd[CMD_LEN_MAX];
		char *nnnfile = (runfile && *runfile) ? runfile : "";
		setenv("nnn", nnnfile, 1);
		xstrsncpy(cmd, plugin, sizeof(cmd));
		if (flags & F_NOWAIT)
			spawn(get_shell(), "-c", cmd, NULL, F_NOWAIT | F_NOTRACE | F_MULTI);
		else
			spawn(get_shell(), "-c", cmd, NULL, F_CLI);
	} else {
		char plugpath[PATH_MAX_LEN];
		mkpath(plgpath, plugin, plugpath);
		if (access(plugpath, X_OK) == -1) {
			unlink(tmppath);
			return false;
		}
		if (flags & F_NOWAIT)
			spawn(plugpath, (runfile && *runfile) ? runfile : NULL, *path, NULL, F_NOWAIT | F_NOTRACE);
		else
			spawn(plugpath, (runfile && *runfile) ? runfile : NULL, *path, NULL, F_CLI);
	}

	/* read output: first byte is context, then type, then path */
	{
		int rfd = open(tmppath, O_RDONLY);
		if (rfd != -1) {
			char buf[PATH_MAX_LEN + 8];
			ssize_t n = read(rfd, buf, sizeof(buf) - 1);
			close(rfd);
			if (n > 2) {
				buf[n] = '\\0';
				char *nl = strchr(buf, '\\n');
				if (nl)
					*nl = '\\0';
				/* format: <ctx><type><path> where ctx is '0'-'8' and type 'c' or 'l' */
				char *pth = buf + 2;
				if (n > 2 && *pth) {
					struct stat sb;
					if (buf[1] == 'c' && stat(pth, &sb) == 0) {
						if (S_ISDIR(sb.st_mode)) {
							xstrsncpy(*lastdir_, *path, PATH_MAX_LEN);
							xstrsncpy(*path, pth, PATH_MAX_LEN);
							(*lastname_)[0] = '\\0';
						} else {
							char *d = xdirname(pth);
							xstrsncpy(*lastname_, xbasename(pth), NAME_MAX_LEN + 1);
							xstrsncpy(*lastdir_, *path, PATH_MAX_LEN);
							xstrsncpy(*path, d, PATH_MAX_LEN);
						}
					}
				}
			}
		}
	}
	(void)outdir;
	unlink(tmppath);
	return true;
}

