sess='''
/* ---------------- sessions ---------------- */

typedef struct {
	int ver;
	int pathln[CTX_MAX];
	int lastln[CTX_MAX];
	int nameln[CTX_MAX];
	int fltrln[CTX_MAX];
} session_header_t;

static void save_session(const char *sname, int *presel)
{
	int fd, i;
	session_header_t header = {0};
	bool status = false;
	char ssnpath[PATH_MAX_LEN];
	char spath[PATH_MAX_LEN];

	header.ver = 1;

	for (i = 0; i < CTX_MAX; ++i) {
		if (g_ctx[i].c_cfg.ctxactive) {
			header.pathln[i] = MIN(strlen(g_ctx[i].c_path), PATH_MAX_LEN - 1) + 1;
			header.lastln[i] = MIN(strlen(g_ctx[i].c_last), PATH_MAX_LEN - 1) + 1;
			header.nameln[i] = MIN(strlen(g_ctx[i].c_name), NAME_MAX_LEN) + 1;
			header.fltrln[i] = MIN(strlen(g_ctx[i].c_fltr), NAME_MAX_LEN) + 1;
		}
	}

	mkpath(cfgpath, "sessions", ssnpath);
	mkpath(ssnpath, sname, spath);

	fd = open(spath, O_CREAT | O_WRONLY | O_TRUNC, 0666);
	if (fd == -1) {
		if (presel)
			printwait("failed!", presel);
		return;
	}

	if ((write(fd, &header, sizeof(header)) != (ssize_t)sizeof(header))
	    || (write(fd, &cfg, sizeof(cfg)) != (ssize_t)sizeof(cfg)))
		goto END;

	for (i = 0; i < CTX_MAX; ++i)
		if ((write(fd, &g_ctx[i].c_cfg, sizeof(settings)) != (ssize_t)sizeof(settings))
		    || (write(fd, &g_ctx[i].color, sizeof(uint_t)) != (ssize_t)sizeof(uint_t))
		    || (header.nameln[i] > 0 && write(fd, g_ctx[i].c_name, header.nameln[i]) != header.nameln[i])
		    || (header.lastln[i] > 0 && write(fd, g_ctx[i].c_last, header.lastln[i]) != header.lastln[i])
		    || (header.fltrln[i] > 0 && write(fd, g_ctx[i].c_fltr, header.fltrln[i]) != header.fltrln[i])
		    || (header.pathln[i] > 0 && write(fd, g_ctx[i].c_path, header.pathln[i]) != header.pathln[i]))
			goto END;

	status = true;

END:
	close(fd);

	if (!status && presel)
		printwait("failed!", presel);
}

static bool load_session(const char *sname, char **path, char **lastdir_, char **lastname_, bool restore)
{
	int fd, i = 0;
	session_header_t header;
	bool status = (sname && g_state.picker); /* Picker mode: ignore session */
	char ssnpath[PATH_MAX_LEN];
	char spath[PATH_MAX_LEN];

	mkpath(cfgpath, "sessions", ssnpath);

	if (!restore) {
		if (!sname) {
			sname = xreadline(NULL, "session name: ");
			if (!sname || !*sname)
				return false;
		}
	} else
		sname = "@";

	mkpath(ssnpath, sname, spath);

	fd = open(spath, O_RDONLY, 0666);
	if (fd == -1) {
		if (!status)
			printmsg("invalid session");
		return false;
	}

	status = false;

	if ((read(fd, &header, sizeof(header)) != (ssize_t)sizeof(header)) || (header.ver != 1)
	    || (read(fd, &cfg, sizeof(cfg)) != (ssize_t)sizeof(cfg)))
		goto END;

	g_ctx[cfg.curctx].c_cfg.ctxactive = 0;
	for (; i < CTX_MAX; ++i)
		if ((read(fd, &g_ctx[i].c_cfg, sizeof(settings)) != (ssize_t)sizeof(settings))
		    || (read(fd, &g_ctx[i].color, sizeof(uint_t)) != (ssize_t)sizeof(uint_t))
		    || (header.nameln[i] > 0 && read(fd, g_ctx[i].c_name, header.nameln[i]) != header.nameln[i])
		    || (header.lastln[i] > 0 && read(fd, g_ctx[i].c_last, header.lastln[i]) != header.lastln[i])
		    || (header.fltrln[i] > 0 && read(fd, g_ctx[i].c_fltr, header.fltrln[i]) != header.fltrln[i])
		    || (header.pathln[i] > 0 && read(fd, g_ctx[i].c_path, header.pathln[i]) != header.pathln[i]))
			goto END;

	*path = g_ctx[cfg.curctx].c_path;
	*lastdir_ = g_ctx[cfg.curctx].c_last;
	*lastname_ = g_ctx[cfg.curctx].c_name;
	set_colors();
	status = true;

END:
	close(fd);

	if (!status)
		printmsg("failed!");
	else if (restore)
		unlink(spath);

	return status;
}

/* ---------------- plugins ---------------- */

/* find plugin for key in NNN_PLUG; returns pointer to a static buffer or NULL */
static char *get_plugin_for_key(int key)
{
	static char plugin[NAME_MAX_LEN + 1];
	char *p = plug_env;

	if (!p)
		return NULL;
	while (*p) {
		if (p[0] == key && p[1] == ':') {
			char *end = strchr(p + 2, ';');
			size_t len = end ? (size_t)(end - p - 2) : strlen(p + 2);
			if (len > NAME_MAX_LEN)
				len = NAME_MAX_LEN;
			memcpy(plugin, p + 2, len);
			plugin[len] = '\\0';
			return plugin;
		}
		p = strchr(p, ';');
		if (!p)
			break;
		++p;
	}
	return NULL;
}

static bool run_plugin(char **path, char *file, char *runfile, char **lastname_, char **lastdir_)
{
	bool cmd_as_plugin = false;
	uchar_t flags = 0;
	char *plugin = file;
	char tmppath[PATH_MAX_LEN];
	int fd;
