							xstrsncpy(*lastdir_, *path, PATH_MAX_LEN);
							xstrsncpy(*path, pth, PATH_MAX_LEN);
							(*lastname_)[0] = '\\0';
						} else {
							char *d = xdirname(pth);
							xstrsncpy(*lastname_, xbasename(pth), NAME_MAX_LEN + 1);
							xstrsncpy(*lastdir_, *path, PATH_MAX_LEN);
							xstrsncpy(*path, d, PATH_MAX_LEN);
						}
					}
