static bool unmount(char *name, char *newpath, int *presel, char *currentpath)
{
	static char cmd[] = "fusermount3"; /* Arch Linux utility */
	static bool found = false;
	char mntpath[PATH_MAX_LEN];
	struct stat sb, psb;
	bool child = false, parent = false;

	/* On Ubuntu it's fusermount */
	if (!found && !is_executable_in_path(cmd)) {
		cmd[10] = '\\0';
		found = true;
