		mkpath(currentpath, name, newpath);
		child = lstat(newpath, &sb) != -1;
		parent = lstat(xdirname(newpath), &psb) != -1;
		if (!child && !parent) {
			*presel = MSGWAIT;
			return false;
		}
	}

	if (!child || !S_ISDIR(sb.st_mode) || sb.st_dev == psb.st_dev) {
		/* unmount the current dir if it is a mount point */
		if (!is_prefix(currentpath, mntpath, strlen(mntpath)) || !strcmp(currentpath, mntpath)) {
			printwait("not a mount point", presel);
			return false;
		}
		xstrsncpy(newpath, currentpath, PATH_MAX_LEN);
