		if (spawn(cmd, "-quz", newpath, NULL, F_NORMAL)) {
			printwait("failed!", presel);
			return false;
		}
	}

	if (!strcmp(newpath, currentpath)) {
		/* we were inside the mount point: go up */
		xstrsncpy(currentpath, xdirname(newpath), PATH_MAX_LEN);
	}
	rmdir(newpath);
	return true;
}

