{
	char joined[PATH_MAX_LEN];
	const char *path = filepath;
	char *resolved;
	size_t len;

	if (!path)
		return NULL;

	if (path[0] == '~') {
		if (!homedir)
			return NULL;
		len = xstrsncpy(joined, homedir, PATH_MAX_LEN);
		xstrsncpy(joined + len - 1, path + 1, PATH_MAX_LEN - len + 1);
		path = joined;
	}

	if (path[0] != '/' && cwd) {
		char tmpj[PATH_MAX_LEN];
		len = strlen(cwd);
		if (len + strlen(path) + 2 > PATH_MAX_LEN)
			return NULL;
		mkpath(cwd, path, tmpj);
		xstrsncpy(joined, tmpj, PATH_MAX_LEN);
		path = joined;
	}

	resolved = buf ? buf : malloc(PATH_MAX_LEN);
	if (!resolved)
		return NULL;

	{
		/* normalize: remove . and .. and duplicate slashes */
		char tmp[PATH_MAX_LEN];
		char *out = resolved, *p = tmp, *seg;

		xstrsncpy(tmp, path, PATH_MAX_LEN);
		out[0] = '/';
		out[1] = '\\0';
		if (*p == '/')
			++p;
		while (*p) {
			seg = p;
			while (*p && *p != '/')
				++p;
			if (*p)
				*p++ = '\\0';
			if (!*seg || !strcmp(seg, "."))
				continue;
			if (!strcmp(seg, "..")) {
				char *sl = strrchr(out, '/');
				if (sl && sl != out)
					*sl = '\\0';
				else
					out[1] = '\\0';
				continue;
			}
			{
				size_t ol = strlen(out);
				if (ol > 1) {
					out[ol++] = '/';
					out[ol] = '\\0';
				}
				xstrsncpy(out + ol, seg, PATH_MAX_LEN - ol);
			}
		}
	}
	return resolved;
}

