	if (nnn_help && *nnn_help) {
		char cmd[CMD_LEN_MAX];
		snprintf(cmd, sizeof(cmd), "%s > %s 2>&1", nnn_help, g_tmpfpath);
		spawn(get_shell(), "-c", cmd, NULL, F_SILENT);
	}

	fp = fopen(g_tmpfpath, "a");
	if (!fp) {
		unlink(g_tmpfpath);
		return;
	}

	fputs(helpstr, fp);

	fputs("\\nCONTEXTS\\n", fp);
	for (int i = 0; i < CTX_MAX; ++i) {
		if (i == (int)cfg.curctx || g_ctx[i].c_cfg.ctxactive)
			fprintf(fp, " %d%c %s\\n", i + 1, (i == (int)cfg.curctx) ? '*' : ' ',
				(i == (int)cfg.curctx) ? path : g_ctx[i].c_path);
	}

	if (statvfs(path, &svb) != -1) {
		char avail[32], used[32], size[32];
		xstrsncpy(avail, coolsize((off_t)svb.f_bavail * svb.f_frsize), sizeof(avail));
		xstrsncpy(used, coolsize((off_t)(svb.f_blocks - svb.f_bavail) * svb.f_frsize), sizeof(used));
		xstrsncpy(size, coolsize((off_t)svb.f_blocks * svb.f_frsize), sizeof(size));
		fprintf(fp, "\\nVOLUME: avail:%s used:%s size:%s\\n", avail, used, size);
	}

	fputc('\\n', fp);

	if (bookmark_keys && *bookmark_keys)
		fprintf(fp, "BOOKMARKS\\n%s\\n\\n", bookmark_keys);

	if (plug_env && *plug_env) {
		char *p = plug_env;
		fputs("PLUGIN KEYS\\n", fp);
		while (*p) {
			char *end = strchr(p, ';');
			size_t len = end ? (size_t)(end - p) : strlen(p);
			if (len >= 2 && p[1] == ':')
				fprintf(fp, " %c: %.*s\\n", p[0], (int)(len - 2), p + 2);
			if (!end)
				break;
			p = end + 1;
		}
		fputc('\\n', fp);
	}

	{
		static const char * const envs[] = {"NNN_OPENER", "NNN_COLORS", "NNN_FCOLORS", "NNN_PIPE", "NNN_MCLICK",
			"NNN_SEL", "NNN_ARCHIVE", "NNN_ORDER", "NNN_HELP", "NNN_TRASH", NULL};
		for (int i = 0; envs[i]; ++i) {
			char *v = getenv(envs[i]);
			if (v)
				fprintf(fp, "%s: %s\\n", envs[i], v);
		}
	}

	if (selpath)
		fprintf(fp, "SELECTION FILE: %s\\n", selpath);

	fprintf(fp, "\\nv%s\\nBSD 2-Clause\\nhttps://github.com/jarun/nnn\\n", VERSION);
	fclose(fp);

	open_in_pager(g_tmpfpath);
	unlink(g_tmpfpath);
}

